	const msg = inputEl.val();
	const mid = inputEl.attr('data-mid');

	if (!msg.trim().length) {
		return;
	}

	inputEl.val('');
	inputEl.removeAttr('data-mid');
	messages.updateRemainingLength(inputEl.parent());
	hooks.fire('action:chat.sent', {
