214	func (m *Manager) Install(repo ghrepo.Interface, target string) error {
215		isBin, err := isBinExtension(m.client, repo)
216		if err != nil {
217			if errors.Is(err, releaseNotFoundErr) {
218				if ok, err := repoExists(m.client, repo); err != nil {
219					return err
220				} else if !ok {
221					return repositoryNotFoundErr
222				}
223			} else {
224				return fmt.Errorf("could not check for binary extension: %w", err)
225			}
226		}
227		if isBin {
228			return m.installBin(repo, target)
229		}
230	
231		hs, err := hasScript(m.client, repo)
232		if err != nil {
233			return err
234		}
235		if !hs {
236			return errors.New("extension is not installable: missing executable")
237		}
238	
239		return m.installGit(repo, target)
240	}
