242	func (m *Manager) installBin(repo ghrepo.Interface, target string) error {
243		var r *release
244		var err error
245		isPinned := target != ""
246		if isPinned {
247			r, err = fetchReleaseFromTag(m.client, repo, target)
248		} else {
249			r, err = fetchLatestRelease(m.client, repo)
250		}
251		if err != nil {
252			return err
253		}
254	
255		platform, ext := m.platform()
256		isMacARM := platform == "darwin-arm64"
257		trueARMBinary := false
258	
259		var asset *releaseAsset
260		for _, a := range r.Assets {
261			if strings.HasSuffix(a.Name, platform+ext) {
262				asset = &a
263				trueARMBinary = isMacARM
264				break
265			}
266		}
267	
268		// if using an ARM-based Mac and an arm64 binary is unavailable, fall back to amd64 if a relevant binary is available and Rosetta 2 is installed
269		if asset == nil && isMacARM {
270			for _, a := range r.Assets {
271				if strings.HasSuffix(a.Name, darwinAmd64) {
272					if !hasRosetta() {
273						return fmt.Errorf(
274							"%[1]s unsupported for %[2]s. Install Rosetta with `softwareupdate --install-rosetta` to use the available %[3]s binary, or open an issue: `gh issue create -R %[4]s/%[1]s -t'Support %[2]s'`",
275							repo.RepoName(), platform, darwinAmd64, repo.RepoOwner())
276					}
277	
278					fallbackMessage := fmt.Sprintf("%[1]s not available for %[2]s. Falling back to compatible %[3]s binary", repo.RepoName(), platform, darwinAmd64)
279					fmt.Fprintln(m.io.Out, fallbackMessage)
280	
281					asset = &a
282					break
283				}
284			}
285		}
286	
287		if asset == nil {
288			cs := m.io.ColorScheme()
289			errorMessageInRed := fmt.Sprintf(cs.Red("%[1]s unsupported for %[2]s."), repo.RepoName(), platform)
290			issueCreateCommand := generateMissingBinaryIssueCreateCommand(repo.RepoOwner(), repo.RepoName(), platform)
291	
292			return fmt.Errorf(
293				"%[1]s\n\nTo request support for %[2]s, open an issue on the extension's repo by running the following command:\n\n	`%[3]s`",
294				errorMessageInRed, platform, issueCreateCommand)
295		}
296	
297		name := repo.RepoName()
298		targetDir := filepath.Join(m.installDir(), name)
299	
300		// TODO clean this up if function errs?
301		if !m.dryRunMode {
302			err = os.MkdirAll(targetDir, 0755)
303			if err != nil {
304				return fmt.Errorf("failed to create installation directory: %w", err)
305			}
306		}
307	
308		binPath := filepath.Join(targetDir, name)
309		binPath += ext
310	
311		if !m.dryRunMode {
312			err = downloadAsset(m.client, *asset, binPath)
313			if err != nil {
314				return fmt.Errorf("failed to download asset %s: %w", asset.Name, err)
315			}
316			if trueARMBinary {
317				if err := codesignBinary(binPath); err != nil {
318					return fmt.Errorf("failed to codesign downloaded binary: %w", err)
319				}
320			}
321		}
322	
323		manifest := binManifest{
324			Name:     name,
325			Owner:    repo.RepoOwner(),
326			Host:     repo.RepoHost(),
327			Path:     binPath,
328			Tag:      r.Tag,
329			IsPinned: isPinned,
330		}
331	
332		bs, err := yaml.Marshal(manifest)
333		if err != nil {
334			return fmt.Errorf("failed to serialize manifest: %w", err)
335		}
336	
337		if !m.dryRunMode {
338			if err := writeManifest(targetDir, manifestName, bs); err != nil {
339				return err
340			}
341		}
342	
343		return nil
344	}
