373	func (m *Manager) installGit(repo ghrepo.Interface, target string) error {
374		protocol := m.config.GitProtocol(repo.RepoHost()).Value
375		cloneURL := ghrepo.FormatRemoteURL(repo, protocol)
376	
377		var commitSHA string
378		if target != "" {
379			var err error
380			commitSHA, err = fetchCommitSHA(m.client, repo, target)
381			if err != nil {
382				return err
383			}
384		}
385	
386		name := strings.TrimSuffix(path.Base(cloneURL), ".git")
387		targetDir := filepath.Join(m.installDir(), name)
388	
389		_, err := m.gitClient.Clone(cloneURL, []string{targetDir})
390		if err != nil {
391			return err
392		}
393		if commitSHA == "" {
394			return nil
395		}
396	
397		scopedClient := m.gitClient.ForRepo(targetDir)
398		err = scopedClient.CheckoutBranch(commitSHA)
399		if err != nil {
400			return err
401		}
402	
403		pinPath := filepath.Join(targetDir, fmt.Sprintf(".pin-%s", commitSHA))
404		f, err := os.OpenFile(pinPath, os.O_WRONLY|os.O_CREATE, 0600)
405		if err != nil {
406			return fmt.Errorf("failed to create pin file in directory: %w", err)
407		}
408		return f.Close()
409	}
