560	func (m *Manager) Create(name string, tmplType extensions.ExtTemplateType) error {
561		if _, err := m.gitClient.CommandOutput([]string{"init", "--quiet", name}); err != nil {
562			return err
563		}
564	
565		if tmplType == extensions.GoBinTemplateType {
566			return m.goBinScaffolding(name)
567		} else if tmplType == extensions.OtherBinTemplateType {
568			return m.otherBinScaffolding(name)
569		}
570	
571		script := fmt.Sprintf(scriptTmpl, name)
572		if err := writeFile(filepath.Join(name, name), []byte(script), 0755); err != nil {
573			return err
574		}
575	
576		scopedClient := m.gitClient.ForRepo(name)
577		if _, err := scopedClient.CommandOutput([]string{"add", name, "--chmod=+x"}); err != nil {
578			return err
579		}
580	
581		if _, err := scopedClient.CommandOutput([]string{"commit", "-m", "initial commit"}); err != nil {
582			return ErrInitialCommitFailed
583		}
