266	func FetchRepository(client *Client, repo ghrepo.Interface, fields []string) (*Repository, error) {
267		query := fmt.Sprintf(`query RepositoryInfo($owner: String!, $name: String!) {
268			repository(owner: $owner, name: $name) {%s}
269		}`, RepositoryGraphQL(fields))
270	
271		variables := map[string]interface{}{
272			"owner": repo.RepoOwner(),
273			"name":  repo.RepoName(),
274		}
275	
276		var result struct {
277			Repository *Repository
278		}
279		if err := client.GraphQL(repo.RepoHost(), query, variables, &result); err != nil {
280			return nil, err
281		}
282		// The GraphQL API should have returned an error in case of a missing repository, but this isn't
283		// guaranteed to happen when an authentication token with insufficient permissions is being used.
284		if result.Repository == nil {
285			return nil, GraphQLError{
286				GraphQLError: &ghAPI.GraphQLError{
287					Errors: []ghAPI.GraphQLErrorItem{{
288						Type:    "NOT_FOUND",
289						Message: fmt.Sprintf("Could not resolve to a Repository with the name '%s/%s'.", repo.RepoOwner(), repo.RepoName()),
290					}},
291				},
292			}
293		}
294	
295		return InitRepoHostname(result.Repository, repo.RepoHost()), nil
296	}
