406	// RepoNetworkResult describes the relationship between related repositories
407	type RepoNetworkResult struct {
408		ViewerLogin  string
409		Repositories []*Repository
410	}
411	
412	// RepoNetwork inspects the relationship between multiple GitHub repositories
413	func RepoNetwork(client *Client, repos []ghrepo.Interface) (RepoNetworkResult, error) {
414		var hostname string
415		if len(repos) > 0 {
416			hostname = repos[0].RepoHost()
417		}
418	
419		queries := make([]string, 0, len(repos))
420		for i, repo := range repos {
421			queries = append(queries, fmt.Sprintf(`
422			repo_%03d: repository(owner: %q, name: %q) {
423				...repo
424				parent {
425					...repo
426				}
427			}
428			`, i, repo.RepoOwner(), repo.RepoName()))
429		}
430	
431		// Since the query is constructed dynamically, we can't parse a response
432		// format using a static struct. Instead, hold the raw JSON data until we
433		// decide how to parse it manually.
434		graphqlResult := make(map[string]*json.RawMessage)
435		var result RepoNetworkResult
436	
437		err := client.GraphQL(hostname, fmt.Sprintf(`
438		fragment repo on Repository {
439			id
440			name
441			owner { login }
442			viewerPermission
443			defaultBranchRef {
444				name
445			}
446			isPrivate
447		}
448		query RepositoryNetwork {
449			viewer { login }
450			%s
451		}
452		`, strings.Join(queries, "")), nil, &graphqlResult)
453		var graphqlError GraphQLError
454		if errors.As(err, &graphqlError) {
455			// If the only errors are that certain repositories are not found,
456			// continue processing this response instead of returning an error
457			tolerated := true
458			for _, ge := range graphqlError.Errors {
459				if ge.Type != "NOT_FOUND" {
460					tolerated = false
461				}
462			}
463			if tolerated {
464				err = nil
465			}
466		}
467		if err != nil {
468			return result, err
469		}
470	
471		keys := make([]string, 0, len(graphqlResult))
472		for key := range graphqlResult {
473			keys = append(keys, key)
474		}
475		// sort keys to ensure `repo_{N}` entries are processed in order
476		sort.Strings(keys)
477	
478		// Iterate over keys of GraphQL response data and, based on its name,
479		// dynamically allocate the target struct an individual message gets decoded to.
480		for _, name := range keys {
481			jsonMessage := graphqlResult[name]
482			if name == "viewer" {
483				viewerResult := struct {
484					Login string
485				}{}
486				decoder := json.NewDecoder(bytes.NewReader([]byte(*jsonMessage)))
487				if err := decoder.Decode(&viewerResult); err != nil {
488					return result, err
489				}
490				result.ViewerLogin = viewerResult.Login
491			} else if strings.HasPrefix(name, "repo_") {
492				if jsonMessage == nil {
493					result.Repositories = append(result.Repositories, nil)
494					continue
495				}
496				var repo Repository
497				decoder := json.NewDecoder(bytes.NewReader(*jsonMessage))
498				if err := decoder.Decode(&repo); err != nil {
499					return result, err
500				}
501				result.Repositories = append(result.Repositories, InitRepoHostname(&repo, hostname))
502			} else {
503				return result, fmt.Errorf("unknown GraphQL result key %q", name)
504			}
505		}
506		return result, nil
507	}
