530	// ForkRepo forks the repository on GitHub and returns the new repository
531	func ForkRepo(client *Client, repo ghrepo.Interface, org, newName string, defaultBranchOnly bool) (*Repository, error) {
532		path := fmt.Sprintf("repos/%s/forks", ghrepo.FullName(repo))
533	
534		params := map[string]interface{}{}
535		if org != "" {
536			params["organization"] = org
537		}
538		if newName != "" {
539			params["name"] = newName
540		}
541		if defaultBranchOnly {
542			params["default_branch_only"] = true
543		}
544	
545		body := &bytes.Buffer{}
546		enc := json.NewEncoder(body)
547		if err := enc.Encode(params); err != nil {
548			return nil, err
549		}
550	
551		result := repositoryV3{}
552		err := client.REST(repo.RepoHost(), "POST", path, body, &result)
553		if err != nil {
554			return nil, err
555		}
556	
557		newRepo := &Repository{
558			ID:        result.NodeID,
559			Name:      result.Name,
560			CreatedAt: result.CreatedAt,
561			Owner: RepositoryOwner{
562				Login: result.Owner.Login,
563			},
564			ViewerPermission: "WRITE",
565			hostname:         repo.RepoHost(),
566		}
567	
568		// The GitHub API will happily return a HTTP 200 when attempting to fork own repo even though no forking
569		// actually took place. Ensure that we raise an error instead.
570		if ghrepo.IsSame(repo, newRepo) {
571			return newRepo, fmt.Errorf("%s cannot be forked. A single user account cannot own both a parent and fork.", ghrepo.FullName(repo))
572		}
573	
574		return newRepo, nil
575	}
