88	func (e *Extension) CurrentVersion() string {
89	e.mu.RLock()
90	if e.currentVersion != "" {
91	defer e.mu.RUnlock()
92	return e.currentVersion
93	}
94	e.mu.RUnlock()
95	
96	var currentVersion string
97	switch e.kind {
98	case LocalKind:
99	case BinaryKind:
100	if manifest, err := e.loadManifest(); err == nil {
101	currentVersion = manifest.Tag
102	}
103	case GitKind:
104	if sha, err := e.gitClient.CommandOutput([]string{"rev-parse", "HEAD"}); err == nil {
105	currentVersion = string(bytes.TrimSpace(sha))
106	}
107	}
108	
109	e.mu.Lock()
110	e.currentVersion = currentVersion
111	e.mu.Unlock()
112	
113	return e.currentVersion
114	}
115	
116	func (e *Extension) LatestVersion() string {
117	e.mu.RLock()
118	if e.latestVersion != "" {
119	defer e.mu.RUnlock()
120	return e.latestVersion
121	}
122	e.mu.RUnlock()
123	
124	var latestVersion string
125	switch e.kind {
126	case LocalKind:
127	case BinaryKind:
128	repo, err := ghrepo.FromFullName(e.URL())
129	if err != nil {
130	return ""
131	}
132	release, err := fetchLatestRelease(e.httpClient, repo)
133	if err != nil {
134	return ""
135	}
136	latestVersion = release.Tag
137	case GitKind:
138	if lsRemote, err := e.gitClient.CommandOutput([]string{"ls-remote", "origin", "HEAD"}); err == nil {
139	latestVersion = string(bytes.SplitN(lsRemote, []byte("\t"), 2)[0])
140	}
141	}
142	
143	e.mu.Lock()
144	e.latestVersion = latestVersion
145	e.mu.Unlock()
146	
147	return e.latestVersion
148	}
