150	func (e *Extension) IsPinned() bool {
151	e.mu.RLock()
152	if e.isPinned != nil {
153	defer e.mu.RUnlock()
154	return *e.isPinned
155	}
156	e.mu.RUnlock()
157	
158	var isPinned bool
159	switch e.kind {
160	case LocalKind:
161	case BinaryKind:
162	if manifest, err := e.loadManifest(); err == nil {
163	isPinned = manifest.IsPinned
164	}
165	case GitKind:
166	pinPath := filepath.Join(e.Path(), fmt.Sprintf(".pin-%s", e.CurrentVersion()))
167	if _, err := os.Stat(pinPath); err == nil {
168	isPinned = true
169	} else {
170	isPinned = false
171	}
172	}
173	
174	e.mu.Lock()
175	e.isPinned = &isPinned
176	e.mu.Unlock()
177	
178	return *e.isPinned
179	}
