181	func (e *Extension) Owner() string {
182	e.mu.RLock()
183	if e.owner != "" {
184	defer e.mu.RUnlock()
185	return e.owner
186	}
187	e.mu.RUnlock()
188	
189	var owner string
190	switch e.kind {
191	case LocalKind:
192	case BinaryKind:
193	if manifest, err := e.loadManifest(); err == nil {
194	owner = manifest.Owner
195	}
196	case GitKind:
197	if remoteURL, err := e.gitClient.Config("remote.origin.url"); err == nil {
198	if url, err := git.ParseURL(strings.TrimSpace(string(remoteURL))); err == nil {
199	if repo, err := ghrepo.FromURL(url); err == nil {
200	owner = repo.RepoOwner()
201	}
202	}
203	}
204	}
205	
206	e.mu.Lock()
207	e.owner = owner
208	e.mu.Unlock()
209	
210	return e.owner
211	}
