223	func (e *Extension) loadManifest() (binManifest, error) {
224	var bm binManifest
225	dir, _ := filepath.Split(e.Path())
226	manifestPath := filepath.Join(dir, manifestName)
227	manifest, err := os.ReadFile(manifestPath)
228	if err != nil {
229	return bm, fmt.Errorf("could not open %s for reading: %w", manifestPath, err)
230	}
231	err = yaml.Unmarshal(manifest, &bm)
232	if err != nil {
233	return bm, fmt.Errorf("could not parse %s: %w", manifestPath, err)
234	}
235	return bm, nil
236	}
