400	func (m *Manager) installGit(repo ghrepo.Interface, target string) error {
401		protocol := m.config.GitProtocol(repo.RepoHost()).Value
402		cloneURL := ghrepo.FormatRemoteURL(repo, protocol)
403	
404		var commitSHA string
405		if target != "" {
406			var err error
407			commitSHA, err = fetchCommitSHA(m.client, repo, target)
408			if err != nil {
409				return err
410			}
411		}
412	
413		name := strings.TrimSuffix(path.Base(cloneURL), ".git")
414		targetDir := filepath.Join(m.installDir(), name)
415	
416		_, err := m.gitClient.Clone(cloneURL, []string{targetDir})
417		if err != nil {
418			return err
419		}
420		if commitSHA == "" {
421			return nil
422		}
423	
424		scopedClient := m.gitClient.ForRepo(targetDir)
425		err = scopedClient.CheckoutBranch(commitSHA)
