876	    /// Non-panicking version of [`ArgMatches::get_many`]
877	    pub fn try_get_many<T: Any + Clone + Send + Sync + 'static>(
878	        &self,
879	        id: &str,
880	    ) -> Result<Option<ValuesRef<T>>, MatchesError> {
881	        let id = Id::from(id);
882	        let arg = match self.try_get_arg_t::<T>(&id)? {
883	            Some(arg) => arg,
884	            None => return Ok(None),
885	        };
886	        let len = arg.num_vals();
887	        let values = arg.vals_flatten();
888	        let values = ValuesRef {
889	            // enforced by `try_get_arg_t`
890	            iter: values.map(|v| v.downcast_ref::<T>().expect(INTERNAL_ERROR_MSG)),
891	            len,
892	        };
893	        Ok(Some(values))
894	    }
