21	/// **NOTE:** `path` should not contain the root `bin_name`.
22	pub fn find_subcommand_with_path<'help, 'cmd>(
23	p: &'cmd Command<'help>,
24	path: Vec<&str>,
25	) -> &'cmd Command<'help> {
26	let mut cmd = p;
