119	/// Gets all the flags of a [`clap::Command`](Command).
120	/// Includes `help` and `version` depending on the [`clap::Command`] settings.
121	pub fn flags<'help>(p: &Command<'help>) -> Vec<Arg<'help>> {
122	debug!("flags: name={}", p.get_name());
