1	use std::{fmt::Write as _, io::Write};
2	
3	use clap::builder::PossibleValue;
4	use clap::*;
5	
6	use crate::generator::{utils, Generator};
7	
8	/// Generate bash completion file
9	#[derive(Copy, Clone, PartialEq, Eq, Debug)]
10	pub struct Bash;
11	
12	impl Generator for Bash {
13	fn file_name(&self, name: &str) -> String {
14	format!("{}.bash", name)
15	}
16	
17	fn generate(&self, cmd: &Command, buf: &mut dyn Write) {
18	let bin_name = cmd
19	.get_bin_name()
20	.expect("crate::generate should have set the bin_name");
21	
22	w!(
23	buf,
24	format!(
25	"_{name}() {{
26	local i cur prev opts cmds
27	COMPREPLY=()
28	cur=\"${{COMP_WORDS[COMP_CWORD]}}\"
29	prev=\"${{COMP_WORDS[COMP_CWORD-1]}}\"
30	cmd=\"\"
31	opts=\"\"
32	
33	for i in ${{COMP_WORDS[@]}}
34	do
35	case \"${{i}}\" in
36	\"$1\")
37	cmd=\"{cmd}\"
38	;;{subcmds}
39	*)
40	;;
41	esac
42	done
43	
44	case \"${{cmd}}\" in
45	{cmd})
46	opts=\"{name_opts}\"
47	if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq 1 ]] ; then
48	COMPREPLY=( $(compgen -W \"${{opts}}\" -- \"${{cur}}\") )
49	return 0
50	fi
51	case \"${{prev}}\" in{name_opts_details}
52	*)
53	COMPREPLY=()
54	;;
55	esac
56	COMPREPLY=( $(compgen -W \"${{opts}}\" -- \"${{cur}}\") )
57	return 0
58	;;{subcmd_details}
59	esac
60	}}
61	
62	complete -F _{name} -o bashdefault -o default {name}
63	",
64	name = bin_name,
65	cmd = bin_name.replace('-', "__"),
66	name_opts = all_options_for_path(cmd, bin_name),
67	name_opts_details = option_details_for_path(cmd, bin_name),
68	subcmds = all_subcommands(cmd),
69	subcmd_details = subcommand_details(cmd)
70	)
71	.as_bytes()
72	);
73	}
74	}
75	
76	fn all_subcommands(cmd: &Command) -> String {
77	debug!("all_subcommands");
78	
79	let mut subcmds = vec![String::new()];
80	let mut scs = utils::all_subcommands(cmd)
81	.iter()
82	.map(|x| x.0.clone())
83	.collect::<Vec<_>>();
84	
85	scs.sort();
86	scs.dedup();
87	
88	subcmds.extend(scs.iter().map(|sc| {
89	format!(
90	"{name})
91	cmd+=\"__{fn_name}\"
92	;;",
93	name = sc,
94	fn_name = sc.replace('-', "__")
95	)
96	}));
97	
98	subcmds.join("\n            ")
99	}
100	
101	fn subcommand_details(cmd: &Command) -> String {
102	debug!("subcommand_details");
103	
104	let mut subcmd_dets = vec![String::new()];
105	let mut scs = utils::all_subcommands(cmd)
106	.iter()
107	.map(|x| x.1.replace(' ', "__"))
108	.collect::<Vec<_>>();
109	
110	scs.sort();
111	
112	subcmd_dets.extend(scs.iter().map(|sc| {
113	format!(
114	"{subcmd})
115	opts=\"{sc_opts}\"
116	if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq {level} ]] ; then
117	COMPREPLY=( $(compgen -W \"${{opts}}\" -- \"${{cur}}\") )
118	return 0
119	fi
120	case \"${{prev}}\" in{opts_details}
121	*)
122	COMPREPLY=()
123	;;
124	esac
125	COMPREPLY=( $(compgen -W \"${{opts}}\" -- \"${{cur}}\") )
126	return 0
127	;;",
128	subcmd = sc.replace('-', "__"),
129	sc_opts = all_options_for_path(cmd, sc),
130	level = sc.split("__").map(|_| 1).sum::<u64>(),
131	opts_details = option_details_for_path(cmd, sc)
132	)
133	}));
134	
135	subcmd_dets.join("\n        ")
136	}
137	
138	fn option_details_for_path(cmd: &Command, path: &str) -> String {
139	debug!("option_details_for_path: path={}", path);
140	
141	let p = utils::find_subcommand_with_path(cmd, path.split("__").skip(1).collect());
142	let mut opts = vec![String::new()];
143	
144	for o in p.get_opts() {
145	if let Some(longs) = o.get_long_and_visible_aliases() {
146	opts.extend(longs.iter().map(|long| {
147	format!(
148	"--{})
149	COMPREPLY=({})
150	return 0
151	;;",
152	long,
153	vals_for(o)
154	)
155	}));
156	}
157	
158	if let Some(shorts) = o.get_short_and_visible_aliases() {
159	opts.extend(shorts.iter().map(|short| {
160	format!(
161	"-{})
162	COMPREPLY=({})
163	return 0
164	;;",
165	short,
166	vals_for(o)
167	)
168	}));
169	}
170	}
171	
172	opts.join("\n                ")
173	}
174	
175	fn vals_for(o: &Arg) -> String {
176	debug!("vals_for: o={}", o.get_id());
177	
178	if let Some(vals) = crate::generator::utils::possible_values(o) {
179	format!(
180	"$(compgen -W \"{}\" -- \"${{cur}}\")",
181	vals.iter()
182	.filter(|pv| !pv.is_hide_set())
183	.map(PossibleValue::get_name)
184	.collect::<Vec<_>>()
185	.join(" ")
186	)
187	} else {
188	String::from("$(compgen -f \"${cur}\")")
189	}
190	}
191	
192	fn all_options_for_path(cmd: &Command, path: &str) -> String {
193	debug!("all_options_for_path: path={}", path);
194	
195	let p = utils::find_subcommand_with_path(cmd, path.split("__").skip(1).collect());
196	
197	let mut opts = String::new();
198	for short in utils::shorts_and_visible_aliases(p) {
199	write!(&mut opts, "-{} ", short).unwrap();
200	}
201	for long in utils::longs_and_visible_aliases(p) {
202	write!(&mut opts, "--{} ", long).unwrap();
203	}
204	for pos in p.get_positionals() {
205	if let Some(vals) = utils::possible_values(pos) {
206	for value in vals {
207	write!(&mut opts, "{} ", value.get_name()).unwrap();
208	}
209	} else {
210	write!(&mut opts, "{} ", pos).unwrap();
211	}
212	}
213	for (sc, _) in utils::subcommands(p) {
214	write!(&mut opts, "{} ", sc).unwrap();
215	}
216	opts.pop();
217	
218	opts
219	}
