48	/// Determine if a regex pattern contains a literal uppercase character.
49	pub fn pattern_has_uppercase_char(pattern: &str) -> bool {
50	let mut parser = ParserBuilder::new().allow_invalid_utf8(true).build();
51	
52	parser
53	.parse(pattern)
54	.map(|hir| hir_has_uppercase_char(&hir))
55	.unwrap_or(false)
56	}
57	
58	/// Determine if a regex expression contains a literal uppercase character.
59	fn hir_has_uppercase_char(hir: &Hir) -> bool {
60	use regex_syntax::hir::*;
61	
62	match *hir.kind() {
63	HirKind::Literal(Literal::Unicode(c)) => c.is_uppercase(),
64	HirKind::Literal(Literal::Byte(b)) => char::from(b).is_uppercase(),
65	HirKind::Class(Class::Unicode(ref ranges)) => ranges
66	.iter()
67	.any(|r| r.start().is_uppercase() || r.end().is_uppercase()),
68	HirKind::Class(Class::Bytes(ref ranges)) => ranges
69	.iter()
70	.any(|r| char::from(r.start()).is_uppercase() || char::from(r.end()).is_uppercase()),
71	HirKind::Group(Group { ref hir, .. }) | HirKind::Repetition(Repetition { ref hir, .. }) => {
72	hir_has_uppercase_char(hir)
73	}
74	HirKind::Concat(ref hirs) | HirKind::Alternation(ref hirs) => {
75	hirs.iter().any(hir_has_uppercase_char)
76	}
77	_ => false,
78	}
79	}
