84	/// Traverse args_os, looking for -exec and replacing it with --exec.
85	///
86	/// # Returns
87	///
88	/// * The args, with substitution if required
89	pub fn transform_args_with_exec<I>(original: I) -> Vec<OsString>
90	where
91	I: Iterator<Item = OsString>,
92	{
93	let mut in_exec_opt = false;
94	let target = OsString::from("-exec");
95	let long_start = OsString::from("--exec");
96	let short_start = OsString::from("-x");
97	let exec_end = OsString::from(";");
98	
99	original.fold(vec![], |mut args, curr| {
100	if in_exec_opt {
101	if curr == exec_end {
102	in_exec_opt = false;
103	}
104	args.push(curr);
105	return args;
106	}
107	
108	if curr == target || curr == long_start || curr == short_start {
109	args.push(if curr == target {
110	OsString::from("--exec")
111	} else {
112	curr
113	});
114	in_exec_opt = true;
115	} else {
116	args.push(curr);
117	}
118	args
119	})
120	}
