42	fn main() {
43	let checked_args = transform_args_with_exec(env::args_os());
44	let matches = app::build_app().get_matches_from(checked_args);
45	
46	// Set the current working directory of the process
47	if let Some(base_directory) = matches.value_of("base-directory") {
48	let basedir = Path::new(base_directory);
49	if !fshelper::is_dir(basedir) {
50	print_error_and_exit!(
51	"The '--base-directory' path ('{}') is not a directory.",
52	basedir.to_string_lossy()
53	);
54	}
55	if let Err(e) = env::set_current_dir(basedir) {
56	print_error_and_exit!(
57	"Could not set '{}' as the current working directory: {}",
58	basedir.to_string_lossy(),
59	e
60	);
61	}
62	}
63	
64	// Get the search pattern
65	let pattern = matches.value_of("pattern").unwrap_or("");
66	
67	// Get the current working directory
68	let current_dir = Path::new(".");
69	if !fshelper::is_dir(current_dir) {
70	print_error_and_exit!("Could not get current directory.");
71	}
72	
73	// Get one or more root directories to search.
74	let mut dir_vec: Vec<_> = match matches
75	.values_of("path")
76	.or_else(|| matches.values_of("search-path"))
77	{
78	Some(paths) => paths
79	.map(|path| {
80	let path_buffer = PathBuf::from(path);
81	if !fshelper::is_dir(&path_buffer) {
82	print_error_and_exit!(
83	"'{}' is not a directory.",
84	path_buffer.to_string_lossy()
85	);
86	}
87	path_buffer
88	})
89	.collect::<Vec<_>>(),
90	None => vec![current_dir.to_path_buf()],
91	};
92	
93	if matches.is_present("absolute-path") {
94	dir_vec = dir_vec
95	.iter()
96	.map(|path_buffer| {
97	path_buffer
98	.canonicalize()
99	.and_then(|pb| fshelper::absolute_path(pb.as_path()))
100	.unwrap()
101	})
102	.collect();
103	}
104	
105	// Detect if the user accidentally supplied a path instead of a search pattern
106	if !matches.is_present("full-path")
107	&& pattern.contains(std::path::MAIN_SEPARATOR)
108	&& fshelper::is_dir(Path::new(pattern))
109	{
110	print_error_and_exit!(
111	"The search pattern '{pattern}' contains a path-separation character ('{sep}') \
112	and will not lead to any search results.\n\n\
113	If you want to search for all files inside the '{pattern}' directory, use a match-all pattern:\n\n  \
114	fd . '{pattern}'\n\n\
115	Instead, if you want to search for the pattern in the full path, use:\n\n  \
116	fd --full-path '{pattern}'",
117	pattern = pattern,
118	sep = std::path::MAIN_SEPARATOR,
119	);
120	}
121	
122	let pattern_regex = if matches.is_present("glob") {
123	let glob = match Glob::new(pattern) {
124	Ok(glob) => glob,
125	Err(e) => {
126	print_error_and_exit!("{}", e);
127	}
128	};
129	glob.regex().to_owned()
130	} else if matches.is_present("fixed-strings") {
131	// Treat pattern as literal string if '--fixed-strings' is used
132	regex::escape(pattern)
133	} else {
134	String::from(pattern)
135	};
136	
137	// The search will be case-sensitive if the command line flag is set or
138	// if the pattern has an uppercase character (smart case).
139	let case_sensitive = !matches.is_present("ignore-case")
140	&& (matches.is_present("case-sensitive") || pattern_has_uppercase_char(&pattern_regex));
141	
142	let colored_output = match matches.value_of("color") {
143	Some("always") => true,
144	Some("never") => false,
145	_ => env::var_os("NO_COLOR").is_none() && atty::is(Stream::Stdout),
146	};
147	
148	let path_separator = matches.value_of("path-separator").map(|str| str.to_owned());
149	
150	#[cfg(windows)]
151	let colored_output = colored_output && ansi_term::enable_ansi_support().is_ok();
152	
153	let ls_colors = if colored_output {
154	Some(LsColors::from_env().unwrap_or_default())
155	} else {
156	None
157	};
158	
159	let command = matches
160	.values_of("exec")
161	.map(CommandTemplate::new)
162	.or_else(|| {
163	matches.values_of("exec-batch").map(|m| {
164	CommandTemplate::new_batch(m).unwrap_or_else(|e| {
165	print_error_and_exit!("{}", e);
166	})
167	})
168	});
169	
170	let size_limits: Vec<SizeFilter> = matches
171	.values_of("size")
172	.map(|v| {
173	v.map(|sf| {
174	if let Some(f) = SizeFilter::from_string(sf) {
175	return f;
176	}
177	print_error_and_exit!("'{}' is not a valid size constraint. See 'fd --help'.", sf);
178	})
179	.collect()
180	})
181	.unwrap_or_else(|| vec![]);
182	
183	let now = time::SystemTime::now();
184	let mut time_constraints: Vec<TimeFilter> = Vec::new();
185	if let Some(t) = matches.value_of("changed-within") {
186	if let Some(f) = TimeFilter::after(&now, t) {
187	time_constraints.push(f);
188	} else {
189	print_error_and_exit!("'{}' is not a valid date or duration. See 'fd --help'.", t);
190	}
191	}
192	if let Some(t) = matches.value_of("changed-before") {
193	if let Some(f) = TimeFilter::before(&now, t) {
194	time_constraints.push(f);
195	} else {
196	print_error_and_exit!("'{}' is not a valid date or duration. See 'fd --help'.", t);
197	}
198	}
199	
200	let config = FdOptions {
201	case_sensitive,
202	search_full_path: matches.is_present("full-path"),
203	ignore_hidden: !(matches.is_present("hidden")
204	|| matches.occurrences_of("rg-alias-hidden-ignore") >= 2),
205	read_fdignore: !(matches.is_present("no-ignore")
206	|| matches.is_present("rg-alias-hidden-ignore")),
207	read_vcsignore: !(matches.is_present("no-ignore")
208	|| matches.is_present("rg-alias-hidden-ignore")
209	|| matches.is_present("no-ignore-vcs")),
210	follow_links: matches.is_present("follow"),
211	one_file_system: matches.is_present("one-file-system"),
212	null_separator: matches.is_present("null_separator"),
213	max_depth: matches
214	.value_of("depth")
215	.or_else(|| matches.value_of("rg-depth"))
216	.and_then(|n| usize::from_str_radix(n, 10).ok()),
217	threads: std::cmp::max(
218	matches
219	.value_of("threads")
220	.and_then(|n| usize::from_str_radix(n, 10).ok())
221	.unwrap_or_else(num_cpus::get),
222	1,
223	),
224	max_buffer_time: matches
225	.value_of("max-buffer-time")
226	.and_then(|n| u64::from_str_radix(n, 10).ok())
227	.map(time::Duration::from_millis),
228	ls_colors,
229	file_types: matches.values_of("file-type").map(|values| {
230	let mut file_types = FileTypes::default();
231	for value in values {
232	match value {
233	"f" | "file" => file_types.files = true,
234	"d" | "directory" => file_types.directories = true,
235	"l" | "symlink" => file_types.symlinks = true,
236	"x" | "executable" => {
237	file_types.executables_only = true;
238	file_types.files = true;
239	}
240	"e" | "empty" => {
241	file_types.empty_only = true;
242	}
243	_ => unreachable!(),
244	}
245	}
246	
247	// If only 'empty' was specified, search for both files and directories:
248	if file_types.empty_only && !(file_types.files || file_types.directories) {
249	file_types.files = true;
250	file_types.directories = true;
251	}
252	
253	file_types
254	}),
255	extensions: matches.values_of("extension").map(|exts| {
256	let patterns = exts
257	.map(|e| e.trim_start_matches('.'))
258	.map(|e| format!(r".\.{}$", regex::escape(e)));
259	match RegexSetBuilder::new(patterns)
260	.case_insensitive(true)
261	.build()
262	{
263	Ok(re) => re,
264	Err(err) => {
265	print_error_and_exit!("{}", err.to_string());
266	}
267	}
268	}),
269	command: command.map(Arc::new),
270	exclude_patterns: matches
271	.values_of("exclude")
272	.map(|v| v.map(|p| String::from("!") + p).collect())
273	.unwrap_or_else(|| vec![]),
274	ignore_files: matches
275	.values_of("ignore-file")
276	.map(|vs| vs.map(PathBuf::from).collect())
277	.unwrap_or_else(|| vec![]),
278	size_constraints: size_limits,
279	time_constraints,
280	show_filesystem_errors: matches.is_present("show-errors"),
281	path_separator,
282	};
283	
284	match RegexBuilder::new(&pattern_regex)
285	.case_insensitive(!config.case_sensitive)
286	.dot_matches_new_line(true)
287	.build()
288	{
289	Ok(re) => {
290	let exit_code = walk::scan(&dir_vec, Arc::new(re), Arc::new(config));
291	process::exit(exit_code.into());
292	}
293	Err(err) => {
294	print_error_and_exit!(
295	"{}\nHint: You can use the '--fixed-strings' option to search for a \
296	literal string instead of a regular expression",
297	err.to_string()
298	);
299	}
300	}
