22	/// Remove the `./` prefix from a path.
23	fn strip_current_dir(pathbuf: &PathBuf) -> &Path {
24	let mut iter = pathbuf.components();
25	let mut iter_next = iter.clone();
26	if iter_next.next() == Some(Component::CurDir) {
27	iter.next();
28	}
29	iter.as_path()
30	}
