32	pub fn print_entry(
33	stdout: &mut StdoutLock,
34	entry: &PathBuf,
35	config: &FdOptions,
36	wants_to_quit: &Arc<AtomicBool>,
37	) {
38	let path = if entry.is_absolute() {
39	entry.as_path()
40	} else {
41	strip_current_dir(entry)
42	};
43	
44	let r = if let Some(ref ls_colors) = config.ls_colors {
45	print_entry_colorized(stdout, path, config, ls_colors, &wants_to_quit)
46	} else {
47	print_entry_uncolorized(stdout, path, config)
48	};
49	
50	if r.is_err() {
51	// Probably a broken pipe. Exit gracefully.
52	process::exit(ExitCode::GeneralError.into());
53	}
54	}
55	
56	fn replace_path_separator<'a>(config: &FdOptions, path: &mut Cow<'a, str>) {
57	match &config.path_separator {
58	None => {}
59	Some(sep) => {
60	*path.to_mut() = path.replace(std::path::MAIN_SEPARATOR, &sep);
61	}
62	}
63	}
64	
65	fn print_entry_colorized(
66	stdout: &mut StdoutLock,
67	path: &Path,
68	config: &FdOptions,
69	ls_colors: &LsColors,
70	wants_to_quit: &Arc<AtomicBool>,
71	) -> io::Result<()> {
72	let default_style = ansi_term::Style::default();
73	
74	// Traverse the path and colorize each component
75	for (component, style) in ls_colors.style_for_path_components(path) {
76	let style = style
77	.map(Style::to_ansi_term_style)
78	.unwrap_or(default_style);
79	
80	let mut path_string = component.to_string_lossy();
81	replace_path_separator(&config, &mut path_string);
82	write!(stdout, "{}", style.paint(path_string))?;
83	
84	if wants_to_quit.load(Ordering::Relaxed) {
85	writeln!(stdout)?;
86	process::exit(ExitCode::KilledBySigint.into());
87	}
88	}
89	
90	if config.null_separator {
91	write!(stdout, "\0")
92	} else {
93	writeln!(stdout)
94	}
95	}
96	
97	fn print_entry_uncolorized(
98	stdout: &mut StdoutLock,
99	path: &Path,
100	config: &FdOptions,
101	) -> io::Result<()> {
102	let separator = if config.null_separator { "\0" } else { "\n" };
103	
104	let mut path_str = path.to_string_lossy();
105	replace_path_separator(&config, &mut path_str);
106	write!(stdout, "{}{}", path_str, separator)
107	}
