31	/// The receiver thread can either be buffering results or directly streaming to the console.
32	enum ReceiverMode {
33	    /// Receiver is still buffering in order to sort the results, if the search finishes fast
34	    /// enough.
35	    Buffering,
36	
37	    /// Receiver is directly printing results to the output.
38	    Streaming,
39	}
