47	/// Recursively scan the given search path for files / pathnames matching the pattern.
48	///
49	/// If the `--exec` argument was supplied, this will create a thread pool for executing
50	/// jobs in parallel from a given command line and the discovered paths. Otherwise, each
51	/// path will simply be written to standard output.
52	pub fn scan(path_vec: &[PathBuf], pattern: Arc<Regex>, config: Arc<FdOptions>) -> ExitCode {
53	    let mut path_iter = path_vec.iter();
54	    let first_path_buf = path_iter
55	        .next()
56	        .expect("Error: Path vector can not be empty");
57	    let (tx, rx) = channel();
58	
59	    let mut override_builder = OverrideBuilder::new(first_path_buf.as_path());
60	
61	    for pattern in &config.exclude_patterns {
62	        let res = override_builder.add(pattern);
63	        if res.is_err() {
64	            print_error_and_exit!("Malformed exclude pattern '{}'", pattern);
65	        }
66	    }
67	    let overrides = override_builder.build().unwrap_or_else(|_| {
68	        print_error_and_exit!("Mismatch in exclude patterns");
69	    });
70	
71	    let mut walker = WalkBuilder::new(first_path_buf.as_path());
72	    walker
73	        .hidden(config.ignore_hidden)
74	        .ignore(config.read_fdignore)
75	        .parents(config.read_fdignore || config.read_vcsignore)
76	        .git_ignore(config.read_vcsignore)
77	        .git_global(config.read_vcsignore)
78	        .git_exclude(config.read_vcsignore)
79	        .overrides(overrides)
80	        .follow_links(config.follow_links)
81	        // No need to check for supported platforms, option is unavailable on unsupported ones
82	        .same_file_system(config.one_file_system)
83	        .max_depth(config.max_depth);
84	
85	    if config.read_fdignore {
86	        walker.add_custom_ignore_filename(".fdignore");
87	    }
88	
89	    for ignore_file in &config.ignore_files {
90	        let result = walker.add_ignore(ignore_file);
91	        match result {
92	            Some(ignore::Error::Partial(_)) => (),
93	            Some(err) => {
94	                print_error!(
95	                    "{}",
96	                    format!(
97	                        "Malformed pattern in custom ignore file. {}.",
98	                        err.to_string()
99	                    )
100	                );
101	            }
102	            None => (),
103	        }
104	    }
105	
106	    for path_entry in path_iter {
107	        walker.add(path_entry.as_path());
108	    }
109	
110	    let parallel_walker = walker.threads(config.threads).build_parallel();
111	
112	    let wants_to_quit = Arc::new(AtomicBool::new(false));
113	    if config.ls_colors.is_some() && config.command.is_none() {
114	        let wq = Arc::clone(&wants_to_quit);
115	        ctrlc::set_handler(move || {
116	            if wq.load(Ordering::Relaxed) {
117	                // Ctrl-C has been pressed twice, exit NOW
118	                process::exit(ExitCode::KilledBySigint.into());
119	            } else {
120	                wq.store(true, Ordering::Relaxed);
121	            }
122	        })
123	        .unwrap();
124	    }
125	
126	    // Spawn the thread that receives all results through the channel.
127	    let receiver_thread = spawn_receiver(&config, &wants_to_quit, rx);
128	
129	    // Spawn the sender threads.
130	    spawn_senders(&config, &wants_to_quit, pattern, parallel_walker, tx);
131	
132	    // Wait for the receiver thread to print out all results.
133	    let exit_code = receiver_thread.join().unwrap();
134	
135	    if wants_to_quit.load(Ordering::Relaxed) {
136	        process::exit(ExitCode::KilledBySigint.into());
137	    }
138	
139	    exit_code
140	}
