142	fn spawn_receiver(
143	    config: &Arc<FdOptions>,
144	    wants_to_quit: &Arc<AtomicBool>,
145	    rx: Receiver<WorkerResult>,
146	) -> thread::JoinHandle<ExitCode> {
147	    let config = Arc::clone(config);
148	    let wants_to_quit = Arc::clone(wants_to_quit);
149	
150	    let show_filesystem_errors = config.show_filesystem_errors;
151	    let threads = config.threads;
152	
153	    thread::spawn(move || {
154	        // This will be set to `Some` if the `--exec` argument was supplied.
155	        if let Some(ref cmd) = config.command {
156	            if cmd.in_batch_mode() {
157	                exec::batch(rx, cmd, show_filesystem_errors)
158	            } else {
159	                let shared_rx = Arc::new(Mutex::new(rx));
160	
161	                let out_perm = Arc::new(Mutex::new(()));
162	
163	                // Each spawned job will store it's thread handle in here.
164	                let mut handles = Vec::with_capacity(threads);
165	                for _ in 0..threads {
166	                    let rx = Arc::clone(&shared_rx);
167	                    let cmd = Arc::clone(cmd);
168	                    let out_perm = Arc::clone(&out_perm);
169	
170	                    // Spawn a job thread that will listen for and execute inputs.
171	                    let handle =
172	                        thread::spawn(move || exec::job(rx, cmd, out_perm, show_filesystem_errors));
173	
174	                    // Push the handle of the spawned thread into the vector for later joining.
175	                    handles.push(handle);
176	                }
177	
178	                // Wait for all threads to exit before exiting the program.
179	                let mut results: Vec<ExitCode> = Vec::new();
180	                for h in handles {
181	                    results.push(h.join().unwrap());
182	                }
183	
184	                merge_exitcodes(results)
185	            }
186	        } else {
187	            let start = time::Instant::now();
188	
189	            let mut buffer = vec![];
190	
191	            // Start in buffering mode
192	            let mut mode = ReceiverMode::Buffering;
193	
194	            // Maximum time to wait before we start streaming to the console.
195	            let max_buffer_time = config
196	                .max_buffer_time
197	                .unwrap_or_else(|| time::Duration::from_millis(100));
198	
199	            let stdout = io::stdout();
200	            let mut stdout = stdout.lock();
201	
202	            for worker_result in rx {
203	                match worker_result {
204	                    WorkerResult::Entry(value) => {
205	                        match mode {
206	                            ReceiverMode::Buffering => {
207	                                buffer.push(value);
208	
209	                                // Have we reached the maximum buffer size or maximum buffering time?
210	                                if buffer.len() > MAX_BUFFER_LENGTH
211	                                    || time::Instant::now() - start > max_buffer_time
212	                                {
213	                                    // Flush the buffer
214	                                    for v in &buffer {
215	                                        output::print_entry(
216	                                            &mut stdout,
217	                                            v,
218	                                            &config,
219	                                            &wants_to_quit,
220	                                        );
221	                                    }
222	                                    buffer.clear();
223	
224	                                    // Start streaming
225	                                    mode = ReceiverMode::Streaming;
226	                                }
227	                            }
228	                            ReceiverMode::Streaming => {
229	                                output::print_entry(&mut stdout, &value, &config, &wants_to_quit);
230	                            }
231	                        }
232	                    }
233	                    WorkerResult::Error(err) => {
234	                        if show_filesystem_errors {
235	                            print_error!("{}", err);
236	                        }
237	                    }
238	                }
239	            }
240	
241	            // If we have finished fast enough (faster than max_buffer_time), we haven't streamed
242	            // anything to the console, yet. In this case, sort the results and print them:
243	            if !buffer.is_empty() {
244	                buffer.sort();
245	                for value in buffer {
246	                    output::print_entry(&mut stdout, &value, &config, &wants_to_quit);
247	                }
248	            }
249	
250	            ExitCode::Success
251	        }
252	    })
253	}
254	
255	pub enum DirEntry {
256	    Normal(ignore::DirEntry),
257	    BrokenSymlink(PathBuf),
258	}
259	
260	impl DirEntry {
261	    pub fn path(&self) -> &Path {
262	        match self {
263	            DirEntry::Normal(e) => e.path(),
264	            DirEntry::BrokenSymlink(pathbuf) => pathbuf.as_path(),
265	        }
266	    }
267	
268	    pub fn file_type(&self) -> Option<FileType> {
269	        match self {
270	            DirEntry::Normal(e) => e.file_type(),
271	            DirEntry::BrokenSymlink(pathbuf) => {
272	                pathbuf.symlink_metadata().map(|m| m.file_type()).ok()
273	            }
274	        }
275	    }
276	
277	    pub fn metadata(&self) -> Option<Metadata> {
278	        match self {
279	            DirEntry::Normal(e) => e.metadata().ok(),
280	            DirEntry::BrokenSymlink(_) => None,
281	        }
282	    }
283	}
284	
285	fn spawn_senders(
286	    config: &Arc<FdOptions>,
287	    wants_to_quit: &Arc<AtomicBool>,
288	    pattern: Arc<Regex>,
289	    parallel_walker: ignore::WalkParallel,
290	    tx: Sender<WorkerResult>,
291	) {
292	    parallel_walker.run(|| {
293	        let config = Arc::clone(config);
294	        let pattern = Arc::clone(&pattern);
295	        let tx_thread = tx.clone();
296	        let wants_to_quit = Arc::clone(wants_to_quit);
297	
298	        Box::new(move |entry_o| {
299	            if wants_to_quit.load(Ordering::Relaxed) {
300	                return ignore::WalkState::Quit;
301	            }
302	
303	            let entry = match entry_o {
304	                Ok(ref e) if e.depth() == 0 => {
305	                    // Skip the root directory entry.
306	                    return ignore::WalkState::Continue;
307	                }
308	                Ok(e) => DirEntry::Normal(e),
309	                Err(ignore::Error::WithPath {
310	                    path,
311	                    err: inner_err,
312	                }) => match inner_err.as_ref() {
313	                    ignore::Error::Io(io_error)
314	                        if io_error.kind() == io::ErrorKind::NotFound
315	                            && path
316	                                .symlink_metadata()
317	                                .ok()
318	                                .map_or(false, |m| m.file_type().is_symlink()) =>
319	                    {
320	                        DirEntry::BrokenSymlink(path.to_owned())
321	                    }
322	                    _ => {
323	                        tx_thread
324	                            .send(WorkerResult::Error(ignore::Error::WithPath {
325	                                path,
326	                                err: inner_err,
327	                            }))
328	                            .unwrap();
329	                        return ignore::WalkState::Continue;
330	                    }
331	                },
332	                Err(err) => {
333	                    tx_thread.send(WorkerResult::Error(err)).unwrap();
334	                    return ignore::WalkState::Continue;
335	                }
336	            };
337	
338	            // Check the name first, since it doesn't require metadata
339	            let entry_path = entry.path();
340	
341	            let search_str: Cow<OsStr> = if config.search_full_path {
342	                match fshelper::path_absolute_form(entry_path) {
343	                    Ok(path_abs_buf) => Cow::Owned(path_abs_buf.as_os_str().to_os_string()),
344	                    Err(_) => {
345	                        print_error_and_exit!("Unable to retrieve absolute path.");
346	                    }
347	                }
348	            } else {
349	                match entry_path.file_name() {
350	                    Some(filename) => Cow::Borrowed(filename),
351	                    None => unreachable!(
352	                        "Encountered file system entry without a file name. This should only \
353	                         happen for paths like 'foo/bar/..' or '/' which are not supposed to \
354	                         appear in a file system traversal."
355	                    ),
356	                }
357	            };
358	
359	            if !pattern.is_match(&osstr_to_bytes(search_str.as_ref())) {
360	                return ignore::WalkState::Continue;
361	            }
362	
363	            // Filter out unwanted extensions.
364	            if let Some(ref exts_regex) = config.extensions {
365	                if let Some(path_str) = entry_path.file_name() {
366	                    if !exts_regex.is_match(&osstr_to_bytes(path_str)) {
367	                        return ignore::WalkState::Continue;
368	                    }
369	                } else {
370	                    return ignore::WalkState::Continue;
371	                }
372	            }
373	
374	            // Filter out unwanted file types.
375	            if let Some(ref file_types) = config.file_types {
376	                if let Some(ref entry_type) = entry.file_type() {
377	                    if (!file_types.files && entry_type.is_file())
378	                        || (!file_types.directories && entry_type.is_dir())
379	                        || (!file_types.symlinks && entry_type.is_symlink())
380	                        || (file_types.executables_only
381	                            && !entry
382	                                .metadata()
383	                                .map(|m| fshelper::is_executable(&m))
384	                                .unwrap_or(false))
385	                        || (file_types.empty_only && !fshelper::is_empty(&entry))
386	                        || !(entry_type.is_file() || entry_type.is_dir() || entry_type.is_symlink())
387	                    {
388	                        return ignore::WalkState::Continue;
389	                    }
390	                } else {
391	                    return ignore::WalkState::Continue;
392	                }
393	            }
394	
395	            // Filter out unwanted sizes if it is a file and we have been given size constraints.
396	            if !config.size_constraints.is_empty() {
397	                if entry_path.is_file() {
398	                    if let Ok(metadata) = entry_path.metadata() {
399	                        let file_size = metadata.len();
400	                        if config
401	                            .size_constraints
402	                            .iter()
403	                            .any(|sc| !sc.is_within(file_size))
404	                        {
405	                            return ignore::WalkState::Continue;
406	                        }
407	                    } else {
408	                        return ignore::WalkState::Continue;
409	                    }
410	                } else {
411	                    return ignore::WalkState::Continue;
412	                }
413	            }
414	
415	            // Filter out unwanted modification times
416	            if !config.time_constraints.is_empty() {
417	                let mut matched = false;
418	                if let Ok(metadata) = entry_path.metadata() {
419	                    if let Ok(modified) = metadata.modified() {
420	                        matched = config
421	                            .time_constraints
422	                            .iter()
423	                            .all(|tf| tf.applies_to(&modified));
424	                    }
425	                }
426	                if !matched {
427	                    return ignore::WalkState::Continue;

400	if config
401	.size_constraints
402	.iter()
403	.any(|sc| !sc.is_within(file_size))
404	{
405	return ignore::WalkState::Continue;
406	}
407	} else {
408	return ignore::WalkState::Continue;
409	}
410	} else {
411	return ignore::WalkState::Continue;
412	}
413	}
414	
415	// Filter out unwanted modification times
416	if !config.time_constraints.is_empty() {
417	let mut matched = false;
418	if let Ok(metadata) = entry_path.metadata() {
419	if let Ok(modified) = metadata.modified() {
420	matched = config
421	.time_constraints
422	.iter()
423	.all(|tf| tf.applies_to(&modified));
424	}
425	}
426	if !matched {
427	return ignore::WalkState::Continue;
428	}
429	}
430	
431	let send_result = tx_thread.send(WorkerResult::Entry(entry_path.to_owned()));
432	
433	if !send_result.is_ok() {
434	return ignore::WalkState::Quit;
435	}
436	
437	ignore::WalkState::Continue
438	})
439	});
440	}
