359	pub fn parse_def(
360	    working_set: &mut StateWorkingSet,
361	    lite_command: &LiteCommand,
362	    module_name: Option<&[u8]>,
363	) -> (Pipeline, Option<(Vec<u8>, DeclId)>) {
364	    let spans = &lite_command.parts[..];
365	
366	    let (usage, extra_usage) = working_set.build_usage(&lite_command.comments);
367	
368	    // Checking that the function is used with the correct name
369	    // Maybe this is not necessary but it is a sanity check
370	    // Note: "export def" is treated the same as "def"
371	
372	    let (name_span, split_id) =
373	        if spans.len() > 1 && working_set.get_span_contents(spans[0]) == b"export" {
374	            (spans[1], 2)
375	        } else {
376	            (spans[0], 1)
377	        };
378	
379	    let def_call = working_set.get_span_contents(name_span).to_vec();
380	    if def_call != b"def" && def_call != b"def-env" {
381	        working_set.error(ParseError::UnknownState(
382	            "internal error: Wrong call name for def function".into(),
383	            span(spans),
384	        ));
385	        return (garbage_pipeline(spans), None);
386	    }
387	
388	    // Parsing the spans and checking that they match the register signature
389	    // Using a parsed call makes more sense than checking for how many spans are in the call
390	    // Also, by creating a call, it can be checked if it matches the declaration signature
391	    let (call, call_span) = match working_set.find_decl(&def_call) {
392	        None => {
393	            working_set.error(ParseError::UnknownState(
394	                "internal error: def declaration not found".into(),
395	                span(spans),
396	            ));
397	            return (garbage_pipeline(spans), None);
398	        }
399	        Some(decl_id) => {
400	            working_set.enter_scope();
401	            let (command_spans, rest_spans) = spans.split_at(split_id);

400	            working_set.enter_scope();
401	            let (command_spans, rest_spans) = spans.split_at(split_id);
402	
403	            // Find the first span that is not a flag
404	            let mut decl_name_span = None;
405	
406	            for span in rest_spans {
407	                if !working_set.get_span_contents(*span).starts_with(&[b'-']) {
408	                    decl_name_span = Some(*span);
409	                    break;
410	                }
411	            }
412	
413	            if let Some(name_span) = decl_name_span {
414	                // Check whether name contains [] or () -- possible missing space error
415	                if let Some(err) = detect_params_in_name(
416	                    working_set,
417	                    name_span,
418	                    String::from_utf8_lossy(&def_call).as_ref(),
419	                ) {
420	                    working_set.error(err);
421	                    return (garbage_pipeline(spans), None);
422	                }
423	            }
424	
425	            let starting_error_count = working_set.parse_errors.len();
426	            let ParsedInternalCall { call, output } =
427	                parse_internal_call(working_set, span(command_spans), rest_spans, decl_id);
428	            // This is to preserve the order of the errors so that
429	            // the check errors below come first
430	            let mut new_errors = working_set.parse_errors[starting_error_count..].to_vec();
431	            working_set.parse_errors.truncate(starting_error_count);
432	
433	            working_set.exit_scope();
434	
435	            let call_span = span(spans);
436	            let decl = working_set.get_decl(decl_id);
437	            let sig = decl.signature();
438	
439	            // Let's get our block and make sure it has the right signature
440	            if let Some(arg) = call.positional_nth(2) {
441	                match arg {
442	                    Expression {
443	                        expr: Expr::Block(block_id),
444	                        ..
445	                    }
446	                    | Expression {
447	                        expr: Expr::Closure(block_id),
448	                        ..
449	                    }
450	                    | Expression {
451	                        expr: Expr::RowCondition(block_id),
452	                        ..
453	                    } => {
454	                        let block = working_set.get_block_mut(*block_id);
455	                        block.signature = Box::new(sig.clone());
456	                    }
457	                    _ => {}
458	                }
459	            }
460	
461	            let starting_error_count = working_set.parse_errors.len();
462	            check_call(working_set, call_span, &sig, &call);
463	            working_set.parse_errors.append(&mut new_errors);
464	            if starting_error_count != working_set.parse_errors.len() || call.has_flag("help") {
465	                return (
466	                    Pipeline::from_vec(vec![Expression {
467	                        expr: Expr::Call(call),
468	                        span: call_span,
469	                        ty: output,
470	                        custom_completion: None,
471	                    }]),
472	                    None,
473	                );
474	            }
475	
476	            (call, call_span)
477	        }
478	    };
479	
480	    let has_env = call.has_flag("env");
481	    let has_wrapped = call.has_flag("wrapped");
482	
483	    // All positional arguments must be in the call positional vector by this point
484	    let name_expr = call.positional_nth(0).expect("def call already checked");
485	    let sig = call.positional_nth(1).expect("def call already checked");
486	    let block = call.positional_nth(2).expect("def call already checked");
487	
488	    let name = if let Some(name) = name_expr.as_string() {
489	        if let Some(mod_name) = module_name {
490	            if name.as_bytes() == mod_name {
491	                let name_expr_span = name_expr.span;
492	
493	                working_set.error(ParseError::NamedAsModule(
494	                    "command".to_string(),
495	                    name,
496	                    "main".to_string(),
497	                    name_expr_span,
498	                ));
499	                return (
500	                    Pipeline::from_vec(vec![Expression {
501	                        expr: Expr::Call(call),

500	                    Pipeline::from_vec(vec![Expression {
501	                        expr: Expr::Call(call),
502	                        span: call_span,
503	                        ty: Type::Any,
504	                        custom_completion: None,
505	                    }]),
506	                    None,
507	                );
508	            }
509	        }
510	
511	        name
512	    } else {
513	        working_set.error(ParseError::UnknownState(
514	            "Could not get string from string expression".into(),
515	            name_expr.span,
516	        ));
517	        return (garbage_pipeline(spans), None);
518	    };
519	
520	    let mut result = None;
521	
522	    if let (Some(mut signature), Some(block_id)) = (sig.as_signature(), block.as_block()) {
523	        if has_wrapped {
524	            if let Some(rest) = &signature.rest_positional {
525	                if let Some(var_id) = rest.var_id {
526	                    let rest_var = &working_set.get_variable(var_id);
527	
528	                    if rest_var.ty != Type::Any && rest_var.ty != Type::List(Box::new(Type::String))
529	                    {
530	                        working_set.error(ParseError::TypeMismatchHelp(
531	                            Type::List(Box::new(Type::String)),
532	                            rest_var.ty.clone(),
533	                            rest_var.declaration_span,
534	                            format!("...rest-like positional argument used in 'def --wrapped' supports only strings. Change the type annotation of ...{} to 'string'.", &rest.name)));
535	
536	                        return (
537	                            Pipeline::from_vec(vec![Expression {
538	                                expr: Expr::Call(call),
539	                                span: call_span,
540	                                ty: Type::Any,
541	                                custom_completion: None,
542	                            }]),
543	                            result,
544	                        );
545	                    }
546	                }
547	            } else {
548	                working_set.error(ParseError::MissingPositional("...rest-like positional argument".to_string(), name_expr.span, "def --wrapped must have a ...rest-like positional argument. Add '...rest: string' to the command's signature.".to_string()));
549	
550	                return (
551	                    Pipeline::from_vec(vec![Expression {
552	                        expr: Expr::Call(call),
553	                        span: call_span,
554	                        ty: Type::Any,
555	                        custom_completion: None,
556	                    }]),
557	                    result,
558	                );
559	            }
560	        }
561	
562	        if let Some(decl_id) = working_set.find_predecl(name.as_bytes()) {
563	            let declaration = working_set.get_decl_mut(decl_id);
564	
565	            signature.name = name.clone();
566	            *signature = signature.add_help();
567	            signature.usage = usage;
568	            signature.extra_usage = extra_usage;
569	            signature.allows_unknown_args = has_wrapped;
570	
571	            *declaration = signature.clone().into_block_command(block_id);
572	
573	            let block = working_set.get_block_mut(block_id);
574	            let calls_itself = block_calls_itself(block, decl_id);
575	            block.recursive = Some(calls_itself);
576	            block.signature = signature;
577	            block.redirect_env = def_call == b"def-env" || has_env;
578	
579	            if block.signature.input_output_types.is_empty() {
580	                block
581	                    .signature
582	                    .input_output_types
583	                    .push((Type::Any, Type::Any));
584	            }
585	
586	            let block = working_set.get_block(block_id);
587	
588	            let typecheck_errors = check_block_input_output(working_set, block);
589	
590	            working_set
591	                .parse_errors
592	                .extend_from_slice(&typecheck_errors);
593	
594	            result = Some((name.as_bytes().to_vec(), decl_id));
595	        } else {
596	            working_set.error(ParseError::InternalError(
597	                "Predeclaration failed to add declaration".into(),
598	                name_expr.span,
599	            ));
600	        };
601	    }

