5	#[derive(Debug, Clone, Copy, PartialEq)]
6	pub enum ShapeDescriptorUse {
7	/// Used in an argument position allowing the addition of custom completion
8	Argument,
9	/// Used to define the type of a variable or input/output types
10	Type,
11	}
12	
13	/// equivalent to [`parse_shape_name`] with [`ShapeDescriptorUse::Type`] converting the
14	/// [`SyntaxShape`] to its [`Type`]
15	pub fn parse_type(working_set: &mut StateWorkingSet, bytes: &[u8], span: Span) -> Type {
16	parse_shape_name(working_set, bytes, span, ShapeDescriptorUse::Type).to_type()
17	}
18	
19	/// Parse the literals of [`Type`]-like [`SyntaxShape`]s including inner types.
20	/// Also handles the specification of custom completions with `type@completer`.
21	///
22	/// Restrict the parsing with `use_loc`
23	/// Used in:
24	/// - [`ShapeDescriptorUse::Argument`]
25	///   - `: ` argument type (+completer) positions in signatures
26	/// - [`ShapeDescriptorUse::Type`]
27	///   - `type->type` input/output type pairs
28	///   - `let name: type` variable type infos
29	///
30	/// NOTE: Does not provide a mapping to every [`SyntaxShape`]
31	pub fn parse_shape_name(
32	working_set: &mut StateWorkingSet,
33	bytes: &[u8],
34	span: Span,
35	use_loc: ShapeDescriptorUse,
36	) -> SyntaxShape {
37	let result = match bytes {
38	b"any" => SyntaxShape::Any,
39	b"binary" => SyntaxShape::Binary,
40	b"block" => {
41	working_set.error(ParseError::LabeledErrorWithHelp {
42	error: "Blocks are not support as first-class values".into(),
43	label: "blocks are not supported as values".into(),
44	help: "Use 'closure' instead of 'block'".into(),
45	span,
46	});
47	SyntaxShape::Any
48	}
49	b"bool" => SyntaxShape::Boolean,
50	b"cell-path" => SyntaxShape::CellPath,
51	b"closure" => SyntaxShape::Closure(None), //FIXME: Blocks should have known output types
52	b"datetime" => SyntaxShape::DateTime,
53	b"directory" => SyntaxShape::Directory,
54	b"duration" => SyntaxShape::Duration,
55	b"error" => SyntaxShape::Error,
56	b"float" => SyntaxShape::Float,
57	b"filesize" => SyntaxShape::Filesize,
58	b"glob" => SyntaxShape::GlobPattern,
59	b"int" => SyntaxShape::Int,
60	_ if bytes.starts_with(b"list") => parse_list_shape(working_set, bytes, span, use_loc),
61	b"nothing" => SyntaxShape::Nothing,
62	b"number" => SyntaxShape::Number,
63	b"path" => SyntaxShape::Filepath,
64	b"range" => SyntaxShape::Range,
65	_ if bytes.starts_with(b"record") => {
66	parse_collection_shape(working_set, bytes, span, use_loc)
67	}
68	b"string" => SyntaxShape::String,
69	_ if bytes.starts_with(b"table") => {
70	parse_collection_shape(working_set, bytes, span, use_loc)
71	}
72	_ => {
73	if bytes.contains(&b'@') {
74	let mut split = bytes.splitn(2, |b| b == &b'@');
75	
76	let shape_name = split
77	.next()
78	.expect("If `bytes` contains `@` splitn returns 2 slices");
79	let shape_span = Span::new(span.start, span.start + shape_name.len());
80	let shape = parse_shape_name(working_set, shape_name, shape_span, use_loc);
81	if use_loc != ShapeDescriptorUse::Argument {
82	let illegal_span = Span::new(span.start + shape_name.len(), span.end);
83	working_set.error(ParseError::LabeledError(
84	"Unexpected custom completer in type spec".into(),
85	"Type specifications do not support custom completers".into(),
86	illegal_span,
87	));
88	return shape;
89	}
90	
91	let cmd_span = Span::new(span.start + shape_name.len() + 1, span.end);
92	let cmd_name = split
93	.next()
94	.expect("If `bytes` contains `@` splitn returns 2 slices");
95	
96	let cmd_name = trim_quotes(cmd_name);
97	if cmd_name.is_empty() {
98	working_set.error(ParseError::Expected(
99	"the command name of a completion function",
100	cmd_span,
101	));
102	return shape;
103	}
104	
105	if let Some(decl_id) = working_set.find_decl(cmd_name) {
106	return SyntaxShape::CompleterWrapper(Box::new(shape), decl_id);
107	} else {
108	working_set.error(ParseError::UnknownCommand(cmd_span));
109	return shape;
110	}
111	} else {
112	//TODO: Handle error case for unknown shapes
113	working_set.error(ParseError::UnknownType(span));
114	return SyntaxShape::Any;
115	}
116	}
117	};
118	
119	result
120	}
