39	pub fn is_subtype(&self, other: &Type) -> bool {
40	// Structural subtyping
41	let is_subtype_collection = |this: &[(String, Type)], that: &[(String, Type)]| {
42	if this.is_empty() || that.is_empty() {
43	true
44	} else if this.len() > that.len() {
45	false
46	} else {
47	this.iter().all(|(col_x, ty_x)| {
48	if let Some((_, ty_y)) = that.iter().find(|(col_y, _)| col_x == col_y) {
49	ty_x.is_subtype(ty_y)
50	} else {
51	false
52	}
53	})
54	}
55	};
56	
57	match (self, other) {
58	(t, u) if t == u => true,
59	(Type::Float, Type::Number) => true,
60	(Type::Int, Type::Number) => true,
61	(_, Type::Any) => true,
62	(Type::List(t), Type::List(u)) if t.is_subtype(u) => true, // List is covariant
63	(Type::Record(this), Type::Record(that)) | (Type::Table(this), Type::Table(that)) => {
64	is_subtype_collection(this, that)
65	}
66	_ => false,
67	}
68	}
