153	#[cfg(feature = "std")]
154	thread_local! {
155	static CURRENT_STATE: State = State {
156	default: RefCell::new(Dispatch::none()),
157	can_enter: Cell::new(true),
158	};
159	}
160	
161	static EXISTS: AtomicBool = AtomicBool::new(false);
162	static GLOBAL_INIT: AtomicUsize = AtomicUsize::new(UNINITIALIZED);
163	
164	const UNINITIALIZED: usize = 0;
165	const INITIALIZING: usize = 1;
166	const INITIALIZED: usize = 2;
167	
168	static mut GLOBAL_DISPATCH: Option<Dispatch> = None;
