170	/// The dispatch state of a thread.
171	#[cfg(feature = "std")]
172	struct State {
173	/// This thread's current default dispatcher.
174	default: RefCell<Dispatch>,
175	/// Whether or not we can currently begin dispatching a trace event.
176	///
177	/// This is set to `false` when functions such as `enter`, `exit`, `event`,
178	/// and `new_span` are called on this thread's default dispatcher, to
179	/// prevent further trace events triggered inside those functions from
180	/// creating an infinite recursion. When we finish handling a dispatch, this
181	/// is set back to `true`.
