198	/// Sets this dispatch as the default for the duration of a closure.
199	///
200	/// The default dispatcher is used when creating a new [span] or
201	/// [`Event`].
202	///
203	/// <div class="information">
204	///     <div class="tooltip ignore" style="">ⓘ<span class="tooltiptext">Note</span></div>
205	/// </div>
