229	/// Sets the dispatch as the default dispatch for the duration of the lifetime
230	/// of the returned DefaultGuard
231	///
232	/// <div class="information">
233	///     <div class="tooltip ignore" style="">ⓘ<span class="tooltiptext">Note</span></div>
234	/// </div>
235	/// <div class="example-wrap" style="display:inline-block">
236	/// <pre class="ignore" style="white-space:normal;font:inherit;">
237	///
238	/// **Note**: This function required the Rust standard library.
