244	#[must_use = "Dropping the guard unregisters the dispatcher."]
245	pub fn set_default(dispatcher: &Dispatch) -> DefaultGuard {
246	// When this guard is dropped, the default dispatcher will be reset to the
247	// prior default. Using this ensures that we always reset to the prior
248	// dispatcher even if the thread calling this function panics.
249	State::set_default(dispatcher.clone())
250	}
