252	/// Sets this dispatch as the global default for the duration of the entire program.
253	/// Will be used as a fallback if no thread-local dispatch has been set in a thread
254	/// (using `with_default`.)
255	///
256	/// Can only be set once; subsequent attempts to set the global default will fail.
257	/// Returns `Err` if the global default has already been set.
258	///
259	///
260	/// <div class="information">
261	///     <div class="tooltip compile_fail" style="">&#x26a0; &#xfe0f;<span class="tooltiptext">Warning</span></div>
262	/// </div><div class="example-wrap" style="display:inline-block"><pre class="compile_fail" style="white-space:normal;font:inherit;">
263	/// <strong>Warning</strong>: In general, libraries should <em>not</em> call
264	/// <code>set_global_default()</code>! Doing so will cause conflicts when
265	/// executables that depend on the library try to set the default later.
266	/// </pre></div>
267	///
268	/// [span]: super::span
269	/// [`Subscriber`]: super::subscriber::Subscriber
270	/// [`Event`]: super::event::Event
271	pub fn set_global_default(dispatcher: Dispatch) -> Result<(), SetGlobalDefaultError> {
272	if GLOBAL_INIT.compare_and_swap(UNINITIALIZED, INITIALIZING, Ordering::SeqCst) == UNINITIALIZED
273	{
274	unsafe {
275	GLOBAL_DISPATCH = Some(dispatcher);
276	}
277	GLOBAL_INIT.store(INITIALIZED, Ordering::SeqCst);
278	EXISTS.store(true, Ordering::Release);
279	Ok(())
280	} else {
281	Err(SetGlobalDefaultError { _no_construct: () })
282	}
283	}
