311	/// Executes a closure with a reference to this thread's current [dispatcher].
312	///
313	/// Note that calls to `get_default` should not be nested; if this function is
314	/// called while inside of another `get_default`, that closure will be provided
315	/// with `Dispatch::none` rather than the previously set dispatcher.
316	///
317	/// [dispatcher]: super::dispatcher::Dispatch
318	#[cfg(feature = "std")]
319	pub fn get_default<T, F>(mut f: F) -> T
320	where
321	F: FnMut(&Dispatch) -> T,
322	{
323	CURRENT_STATE
324	.try_with(|state| {
325	if let Some(entered) = state.enter() {
326	return f(&*entered.current());
327	}
328	
329	f(&Dispatch::none())
330	})
331	.unwrap_or_else(|_| f(&Dispatch::none()))
332	}
