334	/// Executes a closure with a reference to this thread's current [dispatcher].
335	///
336	/// Note that calls to `get_default` should not be nested; if this function is
337	/// called while inside of another `get_default`, that closure will be provided
338	/// with `Dispatch::none` rather than the previously set dispatcher.
339	///
340	/// [dispatcher]: super::dispatcher::Dispatch
341	#[cfg(feature = "std")]
342	#[doc(hidden)]
343	#[inline(never)]
344	pub fn get_current<T>(f: impl FnOnce(&Dispatch) -> T) -> Option<T> {
345	CURRENT_STATE
346	.try_with(|state| {
347	let entered = state.enter()?;
348	Some(f(&*entered.current()))
349	})
350	.ok()?
351	}
