353	/// Executes a closure with a reference to the current [dispatcher].
354	///
355	/// [dispatcher]: super::dispatcher::Dispatch
356	#[cfg(not(feature = "std"))]
357	#[doc(hidden)]
358	pub fn get_current<T>(f: impl FnOnce(&Dispatch) -> T) -> Option<T> {
359	let dispatch = get_global()?;
360	Some(f(&dispatch))
361	}
362	
363	/// Executes a closure with a reference to the current [dispatcher].
364	///
365	/// [dispatcher]: super::dispatcher::Dispatch
366	#[cfg(not(feature = "std"))]
367	pub fn get_default<T, F>(mut f: F) -> T
368	where
369	F: FnMut(&Dispatch) -> T,
370	{
371	if let Some(d) = get_global() {
372	f(d)
373	} else {
374	f(&Dispatch::none())
375	}
376	}
