382	unsafe {
383	// This is safe given the invariant that setting the global dispatcher
384	// also sets `GLOBAL_INIT` to `INITIALIZED`.
385	Some(GLOBAL_DISPATCH.as_ref().expect(
386	"invariant violated: GLOBAL_DISPATCH must be initialized before GLOBAL_INIT is set",
387	))
388	}
389	}
