121	    /// Parse the command line arguments for this process.
122	    ///
123	    /// If a CLI usage error occurred, then exit the process and print a usage
124	    /// or error message. Similarly, if the user requested the version of
125	    /// ripgrep, then print the version and exit.
126	    ///
127	    /// Also, initialize a global logger.
128	    pub fn parse() -> Result<Args> {
129	        // We parse the args given on CLI. This does not include args from
130	        // the config. We use the CLI args as an initial configuration while
131	        // trying to parse config files. If a config file exists and has
132	        // arguments, then we re-parse argv, otherwise we just use the matches
133	        // we have here.
134	        let early_matches = ArgMatches::new(clap_matches(env::args_os())?);
135	        set_messages(!early_matches.is_present("no-messages"));
136	        set_ignore_messages(!early_matches.is_present("no-ignore-messages"));
137	
138	        if let Err(err) = Logger::init() {
139	            return Err(format!("failed to initialize logger: {}", err).into());
140	        }
141	        if early_matches.is_present("trace") {
142	            log::set_max_level(log::LevelFilter::Trace);
143	        } else if early_matches.is_present("debug") {
144	            log::set_max_level(log::LevelFilter::Debug);
145	        } else {
146	            log::set_max_level(log::LevelFilter::Warn);
147	        }
148	
149	        let matches = early_matches.reconfigure()?;
150	        // The logging level may have changed if we brought in additional
151	        // arguments from a configuration file, so recheck it and set the log
152	        // level as appropriate.
153	        if matches.is_present("trace") {
154	            log::set_max_level(log::LevelFilter::Trace);
155	        } else if matches.is_present("debug") {
156	            log::set_max_level(log::LevelFilter::Debug);
157	        } else {
158	            log::set_max_level(log::LevelFilter::Warn);
159	        }
160	        set_messages(!matches.is_present("no-messages"));
161	        set_ignore_messages(!matches.is_present("no-ignore-messages"));
162	        matches.to_args()
163	    }
