408	    fn configure_walk_builder(self, builder: &mut WalkBuilder) {
409	        // This isn't entirely optimal. In particular, we will wind up issuing
410	        // a stat for many files redundantly. Aside from having potentially
411	        // inconsistent results with respect to sorting, this is also slow.
412	        // We could fix this here at the expense of memory by caching stat
413	        // calls. A better fix would be to find a way to push this down into
414	        // directory traversal itself, but that's a somewhat nasty change.
415	        match self.kind {
416	            SortByKind::None => {}
417	            SortByKind::Path => {
418	                if self.reverse {
419	                    builder.sort_by_file_name(|a, b| a.cmp(b).reverse());
420	                } else {
421	                    builder.sort_by_file_name(|a, b| a.cmp(b));
422	                }
423	            }
424	            SortByKind::LastModified => {
425	                builder.sort_by_file_path(move |a, b| {
426	                    sort_by_metadata_time(a, b, self.reverse, |md| {
427	                        md.modified()
428	                    })
429	                });
430	            }
431	            SortByKind::LastAccessed => {
432	                builder.sort_by_file_path(move |a, b| {
433	                    sort_by_metadata_time(a, b, self.reverse, |md| {
434	                        md.accessed()
435	                    })
436	                });
437	            }
438	            SortByKind::Created => {
439	                builder.sort_by_file_path(move |a, b| {
440	                    sort_by_metadata_time(a, b, self.reverse, |md| {
441	                        md.created()
442	                    })
443	                });
444	            }
445	        }
446	    }
