729	                // should be big enough for anything. But let's crank it to
730	                // 10MB.
731	                .max_jit_stack_size(Some(10 * (1 << 20)));
732	        }
733	        if self.unicode() {
734	            builder.utf(true).ucp(true);
735	            if self.encoding()?.has_explicit_encoding() {
736	                // SAFETY: If an encoding was specified, then we're guaranteed
737	                // to get valid UTF-8, so we can disable PCRE2's UTF checking.
738	                // (Feeding invalid UTF-8 to PCRE2 is undefined behavior.)
739	                unsafe {
740	                    builder.disable_utf_check();
