742	            }
743	        }
744	        if self.is_present("multiline") {
745	            builder.dotall(self.is_present("multiline-dotall"));
746	        }
747	        if self.is_present("crlf") {
748	            builder.crlf(true);
749	        }
750	        Ok(builder.build(&patterns.join("|"))?)
751	    }
