58	let matched = match args.command() {
59	Search => search(&args),
60	SearchParallel => search_parallel(&args),
61	SearchNever => Ok(false),
62	Files => files(&args),
63	FilesParallel => files_parallel(&args),
64	Types => types(&args),
65	PCRE2Version => pcre2_version(&args),
66	}?;
