124	/// The top-level entry point for multi-threaded search. The parallelism is
125	/// itself achieved by the recursive directory traversal. All we need to do is
126	/// feed it a worker for performing a search on each file.
127	fn search_parallel(args: &Args) -> Result<bool> {
128	use std::sync::atomic::AtomicBool;
129	use std::sync::atomic::Ordering::SeqCst;
130	
131	let quit_after_match = args.quit_after_match()?;
132	let started_at = Instant::now();
133	let subject_builder = args.subject_builder();
134	let bufwtr = args.buffer_writer()?;
135	let stats = args.stats()?.map(Mutex::new);
136	let matched = AtomicBool::new(false);
137	let searched = AtomicBool::new(false);
138	let mut searcher_err = None;
139	args.walker_parallel()?.run(|| {
140	let bufwtr = &bufwtr;
141	let stats = &stats;
142	let matched = &matched;
143	let searched = &searched;
144	let subject_builder = &subject_builder;
145	let mut searcher = match args.search_worker(bufwtr.buffer()) {
146	Ok(searcher) => searcher,
147	Err(err) => {
148	searcher_err = Some(err);
149	return Box::new(move |_| WalkState::Quit);
150	}
151	};
152	
153	Box::new(move |result| {
154	let subject = match subject_builder.build_from_result(result) {
155	Some(subject) => subject,
156	None => return WalkState::Continue,
157	};
158	searched.store(true, SeqCst);
159	searcher.printer().get_mut().clear();
160	let search_result = match searcher.search(&subject) {
161	Ok(search_result) => search_result,
162	Err(err) => {
163	err_message!("{}: {}", subject.path().display(), err);
164	return WalkState::Continue;
165	}
166	};
167	if search_result.has_match() {
168	matched.store(true, SeqCst);
169	}
170	if let Some(ref locked_stats) = *stats {
171	let mut stats = locked_stats.lock().unwrap();
172	*stats += search_result.stats().unwrap();
173	}
174	if let Err(err) = bufwtr.print(searcher.printer().get_mut()) {
175	// A broken pipe means graceful termination.
176	if err.kind() == io::ErrorKind::BrokenPipe {
177	return WalkState::Quit;
178	}
179	// Otherwise, we continue on our merry way.
180	err_message!("{}: {}", subject.path().display(), err);
181	}
182	if matched.load(SeqCst) && quit_after_match {
183	WalkState::Quit
184	} else {
185	WalkState::Continue
186	}
187	})
188	});
189	if let Some(err) = searcher_err.take() {
190	return Err(err);
191	}
192	if args.using_default_path() && !searched.load(SeqCst) {
193	eprint_nothing_searched();
194	}
195	if let Some(ref locked_stats) = stats {
196	let elapsed = Instant::now().duration_since(started_at);
197	let stats = locked_stats.lock().unwrap();
198	let mut searcher = args.search_worker(args.stdout())?;
199	// We don't care if we couldn't print this successfully.
200	let _ = searcher.print_stats(elapsed, &stats);
201	}
202	Ok(matched.load(SeqCst))
203	}
