213	/// The top-level entry point for listing files without searching them. This
214	/// recursively steps through the file list (current directory by default) and
215	/// prints each path sequentially using a single thread.
216	fn files(args: &Args) -> Result<bool> {
217	let quit_after_match = args.quit_after_match()?;
218	let subject_builder = args.subject_builder();
219	let mut matched = false;
220	let mut path_printer = args.path_printer(args.stdout())?;
221	for result in args.walker()? {
222	let subject = match subject_builder.build_from_result(result) {
223	Some(subject) => subject,
224	None => continue,
225	};
226	matched = true;
227	if quit_after_match {
228	break;
229	}
230	if let Err(err) = path_printer.write_path(subject.path()) {
231	// A broken pipe means graceful termination.
232	if err.kind() == io::ErrorKind::BrokenPipe {
233	break;
234	}
235	// Otherwise, we have some other error that's preventing us from
236	// writing to stdout, so we should bubble it up.
237	return Err(err.into());
238	}
239	}
240	Ok(matched)
241	}
