243	/// The top-level entry point for listing files without searching them. This
244	/// recursively steps through the file list (current directory by default) and
245	/// prints each path sequentially using multiple threads.
246	fn files_parallel(args: &Args) -> Result<bool> {
247	use std::sync::atomic::AtomicBool;
248	use std::sync::atomic::Ordering::SeqCst;
249	use std::sync::mpsc;
250	use std::thread;
251	
252	let quit_after_match = args.quit_after_match()?;
253	let subject_builder = args.subject_builder();
254	let mut path_printer = args.path_printer(args.stdout())?;
255	let matched = AtomicBool::new(false);
256	let (tx, rx) = mpsc::channel::<Subject>();
257	
258	let print_thread = thread::spawn(move || -> io::Result<()> {
259	for subject in rx.iter() {
260	path_printer.write_path(subject.path())?;
261	}
262	Ok(())
263	});
264	args.walker_parallel()?.run(|| {
265	let subject_builder = &subject_builder;
266	let matched = &matched;
267	let tx = tx.clone();
268	
269	Box::new(move |result| {
270	let subject = match subject_builder.build_from_result(result) {
271	Some(subject) => subject,
272	None => return WalkState::Continue,
273	};
274	matched.store(true, SeqCst);
275	if quit_after_match {
276	WalkState::Quit
277	} else {
278	match tx.send(subject) {
279	Ok(_) => WalkState::Continue,
280	Err(_) => WalkState::Quit,
281	}
282	}
283	})
284	});
285	drop(tx);
286	if let Err(err) = print_thread.join().unwrap() {
287	// A broken pipe means graceful termination, so fall through.
288	// Otherwise, something bad happened while writing to stdout, so bubble
289	// it up.
290	if err.kind() != io::ErrorKind::BrokenPipe {
291	return Err(err.into());
292	}
293	}
294	Ok(matched.load(SeqCst))
295	}
