297	/// The top-level entry point for --type-list.
298	fn types(args: &Args) -> Result<bool> {
299	let mut count = 0;
300	let mut stdout = args.stdout();
301	for def in args.type_defs()? {
302	count += 1;
303	stdout.write_all(def.name().as_bytes())?;
304	stdout.write_all(b": ")?;
305	
306	let mut first = true;
307	for glob in def.globs() {
308	if !first {
309	stdout.write_all(b", ")?;
310	}
311	stdout.write_all(glob.as_bytes())?;
312	first = false;
313	}
314	stdout.write_all(b"\n")?;
315	}
316	Ok(count > 0)
317	}
