320	fn pcre2_version(args: &Args) -> Result<bool> {
321	#[cfg(feature = "pcre2")]
322	fn imp(args: &Args) -> Result<bool> {
323	use grep::pcre2;
324	
325	let mut stdout = args.stdout();
326	
327	let (major, minor) = pcre2::version();
328	writeln!(stdout, "PCRE2 {}.{} is available", major, minor)?;
329	
330	if cfg!(target_pointer_width = "64") && pcre2::is_jit_available() {
