246	    fn print_stats_human(
247	        &mut self,
248	        total_duration: Duration,
249	        stats: &Stats,
250	    ) -> io::Result<()> {
251	        write!(
252	            self.get_mut(),
253	            "
254	{matches} matches
255	{lines} matched lines
256	{searches_with_match} files contained matches
257	{searches} files searched
258	{bytes_printed} bytes printed
259	{bytes_searched} bytes searched
260	{search_time:0.6} seconds spent searching
261	{process_time:0.6} seconds
262	",
263	            matches = stats.matches(),
264	            lines = stats.matched_lines(),
265	            searches_with_match = stats.searches_with_match(),
266	            searches = stats.searches(),
267	            bytes_printed = stats.bytes_printed(),
268	            bytes_searched = stats.bytes_searched(),
269	            search_time = fractional_seconds(stats.elapsed()),
270	            process_time = fractional_seconds(total_duration)
271	        )
272	    }
