274	    fn print_stats_json(
275	        &mut self,
276	        total_duration: Duration,
277	        stats: &Stats,
278	    ) -> io::Result<()> {
279	        // We specifically match the format laid out by the JSON printer in
280	        // the grep-printer crate. We simply "extend" it with the 'summary'
281	        // message type.
282	        let fractional = fractional_seconds(total_duration);
283	        json::to_writer(
284	            self.get_mut(),
285	            &json!({
286	                "type": "summary",
287	                "data": {
288	                    "stats": stats,
289	                    "elapsed_total": {
290	                        "secs": total_duration.as_secs(),
291	                        "nanos": total_duration.subsec_nanos(),
292	                        "human": format!("{:0.6}s", fractional),
293	                    },
294	                }
295	            }),
296	        )?;
297	        write!(self.get_mut(), "\n")
298	    }
