310	/// A worker for executing searches.
311	///
312	/// It is intended for a single worker to execute many searches, and is
313	/// generally intended to be used from a single thread. When searching using
314	/// multiple threads, it is better to create a new worker for each thread.
315	#[derive(Debug)]
316	pub struct SearchWorker<W> {
317	    config: Config,
318	    command_builder: cli::CommandReaderBuilder,
319	    decomp_builder: cli::DecompressionReaderBuilder,
