325	impl<W: WriteColor> SearchWorker<W> {
326	    /// Execute a search over the given subject.
327	    pub fn search(&mut self, subject: &Subject) -> io::Result<SearchResult> {
328	        let bin = if subject.is_explicit() {
329	            self.config.binary_explicit.clone()
330	        } else {
331	            self.config.binary_implicit.clone()
332	        };
333	        let path = subject.path();
334	        log::trace!("{}: binary detection: {:?}", path.display(), bin);
335	
336	        self.searcher.set_binary_detection(bin);
337	        if subject.is_stdin() {
338	            self.search_reader(path, &mut io::stdin().lock())
339	        } else if self.should_preprocess(path) {
340	            self.search_preprocessor(path)
341	        } else if self.should_decompress(path) {
342	            self.search_decompress(path)
343	        } else {
344	            self.search_path(path)
345	        }
346	    }
347	
348	    /// Return a mutable reference to the underlying printer.
349	    pub fn printer(&mut self) -> &mut Printer<W> {
350	        &mut self.printer
351	    }
352	
353	    /// Print the given statistics to the underlying writer in a way that is
354	    /// consistent with this searcher's printer's format.
355	    ///
356	    /// While `Stats` contains a duration itself, this only corresponds to the
357	    /// time spent searching, where as `total_duration` should roughly
358	    /// approximate the lifespan of the ripgrep process itself.
359	    pub fn print_stats(
360	        &mut self,
361	        total_duration: Duration,
362	        stats: &Stats,
363	    ) -> io::Result<()> {
364	        if self.config.json_stats {
365	            self.printer().print_stats_json(total_duration, stats)
366	        } else {
367	            self.printer().print_stats(total_duration, stats)
368	        }
369	    }
