371	    /// Returns true if and only if the given file path should be
372	    /// decompressed before searching.
373	    fn should_decompress(&self, path: &Path) -> bool {
374	        if !self.config.search_zip {
375	            return false;
376	        }
377	        self.decomp_builder.get_matcher().has_command(path)
378	    }
379	
380	    /// Returns true if and only if the given file path should be run through
381	    /// the preprocessor.
382	    fn should_preprocess(&self, path: &Path) -> bool {
383	        if !self.config.preprocessor.is_some() {
384	            return false;
385	        }
386	        if self.config.preprocessor_globs.is_empty() {
387	            return true;
388	        }
389	        !self.config.preprocessor_globs.matched(path, false).is_ignore()
390	    }
