392	    /// Search the given file path by first asking the preprocessor for the
393	    /// data to search instead of opening the path directly.
394	    fn search_preprocessor(
395	        &mut self,
396	        path: &Path,
397	    ) -> io::Result<SearchResult> {
398	        let bin = self.config.preprocessor.as_ref().unwrap();
399	        let mut cmd = Command::new(bin);
400	        cmd.arg(path).stdin(Stdio::from(File::open(path)?));
401	
402	        let mut rdr = self.command_builder.build(&mut cmd).map_err(|err| {
403	            io::Error::new(
404	                io::ErrorKind::Other,
405	                format!(
406	                    "preprocessor command could not start: '{:?}': {}",
407	                    cmd, err,
408	                ),
409	            )
410	        })?;
411	        let result = self.search_reader(path, &mut rdr).map_err(|err| {
412	            io::Error::new(
413	                io::ErrorKind::Other,
414	                format!("preprocessor command failed: '{:?}': {}", cmd, err),
415	            )
416	        });
417	        let close_result = rdr.close();
418	        let search_result = result?;
419	        close_result?;
420	        Ok(search_result)
421	    }
422	
423	    /// Attempt to decompress the data at the given file path and search the
424	    /// result. If the given file path isn't recognized as a compressed file,
425	    /// then search it without doing any decompression.
426	    fn search_decompress(&mut self, path: &Path) -> io::Result<SearchResult> {
427	        let mut rdr = self.decomp_builder.build(path)?;
428	        let result = self.search_reader(path, &mut rdr);
429	        let close_result = rdr.close();
430	        let search_result = result?;
431	        close_result?;
432	        Ok(search_result)
433	    }
