435	    /// Search the contents of the given file path.
436	    fn search_path(&mut self, path: &Path) -> io::Result<SearchResult> {
437	        use self::PatternMatcher::*;
438	
439	        let (searcher, printer) = (&mut self.searcher, &mut self.printer);
440	        match self.matcher {
441	            RustRegex(ref m) => search_path(m, searcher, printer, path),
442	            #[cfg(feature = "pcre2")]
443	            PCRE2(ref m) => search_path(m, searcher, printer, path),
444	        }
445	    }
