447	    /// Executes a search on the given reader, which may or may not correspond
448	    /// directly to the contents of the given file path. Instead, the reader
449	    /// may actually cause something else to be searched (for example, when
450	    /// a preprocessor is set or when decompression is enabled). In those
451	    /// cases, the file path is used for visual purposes only.
452	    ///
453	    /// Generally speaking, this method should only be used when there is no
454	    /// other choice. Searching via `search_path` provides more opportunities
455	    /// for optimizations (such as memory maps).
456	    fn search_reader<R: io::Read>(
457	        &mut self,
458	        path: &Path,
459	        rdr: &mut R,
460	    ) -> io::Result<SearchResult> {
461	        use self::PatternMatcher::*;
462	
463	        let (searcher, printer) = (&mut self.searcher, &mut self.printer);
464	        match self.matcher {
465	            RustRegex(ref m) => search_reader(m, searcher, printer, path, rdr),
466	            #[cfg(feature = "pcre2")]
467	            PCRE2(ref m) => search_reader(m, searcher, printer, path, rdr),
468	        }
469	    }
470	}
