79	/// Alternation literals checks if the given HIR is a simple alternation of
80	/// literals, and if so, returns them. Otherwise, this returns None.
81	pub fn alternation_literals(expr: &Hir) -> Option<Vec<Vec<u8>>> {
82	use regex_syntax::hir::{HirKind, Literal};
83	
84	// This is pretty hacky, but basically, if `is_alternation_literal` is
85	// true, then we can make several assumptions about the structure of our
86	// HIR. This is what justifies the `unreachable!` statements below.
87	
88	if !expr.is_alternation_literal() {
89	return None;
90	}
91	let alts = match *expr.kind() {
92	HirKind::Alternation(ref alts) => alts,
93	_ => return None, // one literal isn't worth it
94	};
95	
96	let extendlit = |lit: &Literal, dst: &mut Vec<u8>| match *lit {
97	Literal::Unicode(c) => {
98	let mut buf = [0; 4];
99	dst.extend_from_slice(c.encode_utf8(&mut buf).as_bytes());
100	}
101	Literal::Byte(b) => {
102	dst.push(b);
103	}
104	};
105	
106	let mut lits = vec![];
107	for alt in alts {
108	let mut lit = vec![];
109	match *alt.kind() {
110	HirKind::Empty => {}
111	HirKind::Literal(ref x) => extendlit(x, &mut lit),
112	HirKind::Concat(ref exprs) => {
113	for e in exprs {
114	match *e.kind() {
115	HirKind::Literal(ref x) => extendlit(x, &mut lit),
116	_ => unreachable!("expected literal, got {:?}", e),
117	}
118	}
119	}
120	_ => unreachable!("expected literal or concat, got {:?}", alt),
121	}
122	lits.push(lit);
123	}
124	Some(lits)
125	}
