142	/*
143	/**********************************************************************
144	/* Access
145	/**********************************************************************
146	*/
147	
148	/**
149	* General-purpose accessor for finding what to do when specified coercion
150	* from shape that is now always allowed to be coerced from is requested.
151	*
152	* @param config Currently active deserialization configuration
153	* @param targetType Logical target type of coercion
154	* @param targetClass Physical target type of coercion
155	* @param inputShape Input shape to coerce from
156	*
157	* @return CoercionAction configured for specified coercion
158	*
159	* @since 2.12
160	*/
161	public CoercionAction findCoercion(DeserializationConfig config,
162	LogicalType targetType,
163	Class<?> targetClass, CoercionInputShape inputShape)
164	{
165	// First, see if there is exact match for physical type
166	if ((_perClassCoercions != null) && (targetClass != null)) {
167	MutableCoercionConfig cc = _perClassCoercions.get(targetClass);
168	if (cc != null) {
169	CoercionAction act = cc.findAction(inputShape);
170	if (act != null) {
171	return act;
172	}
173	}
174	}
175	
176	// If not, maybe by logical type
177	if ((_perTypeCoercions != null) && (targetType != null)) {
178	MutableCoercionConfig cc = _perTypeCoercions[targetType.ordinal()];
179	if (cc != null) {
180	CoercionAction act = cc.findAction(inputShape);
181	if (act != null) {
182	return act;
183	}
184	}
185	}
186	
187	// Barring that, default coercion for input shape?
188	CoercionAction act = _defaultCoercions.findAction(inputShape);
189	if (act != null) {
190	return act;
191	}
192	
193	// Otherwise there are some legacy features that can provide answer
194	switch (inputShape) {
195	case EmptyArray:
196	// Default for setting is false
197	return config.isEnabled(DeserializationFeature.ACCEPT_EMPTY_ARRAY_AS_NULL_OBJECT) ?
198	CoercionAction.AsNull : CoercionAction.Fail;
199	case Float:
200	if (targetType == LogicalType.Integer) {
201	// Default for setting in 2.x is true
202	return config.isEnabled(DeserializationFeature.ACCEPT_FLOAT_AS_INT) ?
203	CoercionAction.TryConvert : CoercionAction.Fail;
204	}
205	break;
206	case Integer:
207	if (targetType == LogicalType.Enum) {
208	if (config.isEnabled(DeserializationFeature.FAIL_ON_NUMBERS_FOR_ENUMS)) {
209	return CoercionAction.Fail;
210	}
211	}
212	break;
213	default:
214	}
215	
216	// classic scalars are numbers, booleans; but date/time also considered
217	// scalar for this particular purpose
218	final boolean baseScalar = _isScalarType(targetType);
219	
220	if (baseScalar) {
221	// Default for setting in 2.x is true
222	if (!config.isEnabled(MapperFeature.ALLOW_COERCION_OF_SCALARS)) {
223	return CoercionAction.Fail;
224	}
225	}
226	
227	if (inputShape == CoercionInputShape.EmptyString) {
228	// Since coercion of scalar must be enabled (see check above), allow empty-string
229	// coercions by default even without this setting
230	if (baseScalar
231	// Default for setting is false
232	|| config.isEnabled(DeserializationFeature.ACCEPT_EMPTY_STRING_AS_NULL_OBJECT)) {
233	return CoercionAction.AsNull;
234	}
235	// 09-Jun-2020, tatu: Seems necessary to support backwards-compatibility with
236	//     2.11, wrt "FromStringDeserializer" supported types
237	if (targetType == LogicalType.OtherScalar) {
238	return CoercionAction.TryConvert;
239	}
240	// But block from allowing structured types like POJOs, Maps etc
241	return CoercionAction.Fail;
242	}
243	
244	// and all else failing, return default
245	return _defaultAction;
246	}
247	
248	/**
249	* More specialized accessor called in case of input being a blank
250	* String (one consisting of only white space characters with length of at least one).
251	* Will basically first determine if "blank as empty" is allowed: if not,
252	* returns {@code actionIfBlankNotAllowed}, otherwise returns action for
253	* {@link CoercionInputShape#EmptyString}.
254	*
255	* @param config Currently active deserialization configuration
256	* @param targetType Logical target type of coercion
257	* @param targetClass Physical target type of coercion
258	* @param actionIfBlankNotAllowed Return value to use in case "blanks as empty"
259	*    is not allowed
260	*
261	* @return CoercionAction configured for specified coercion from blank string
262	*/
263	public CoercionAction findCoercionFromBlankString(DeserializationConfig config,
264	LogicalType targetType,
265	Class<?> targetClass,
266	CoercionAction actionIfBlankNotAllowed)
267	{
268	Boolean acceptBlankAsEmpty = null;
269	CoercionAction action = null;
270	
271	// First, see if there is exact match for physical type
272	if ((_perClassCoercions != null) && (targetClass != null)) {
273	MutableCoercionConfig cc = _perClassCoercions.get(targetClass);
274	if (cc != null) {
275	acceptBlankAsEmpty = cc.getAcceptBlankAsEmpty();
276	action = cc.findAction(CoercionInputShape.EmptyString);
277	}
278	}
279	
280	// If not, maybe by logical type
281	if ((_perTypeCoercions != null) && (targetType != null)) {
282	MutableCoercionConfig cc = _perTypeCoercions[targetType.ordinal()];
283	if (cc != null) {
284	if (acceptBlankAsEmpty == null) {
285	acceptBlankAsEmpty = cc.getAcceptBlankAsEmpty();
286	}
287	if (action == null) {
288	action = cc.findAction(CoercionInputShape.EmptyString);
289	}
290	}
291	}
292	
293	// Barring that, default coercion for input shape?
294	if (acceptBlankAsEmpty == null) {
295	acceptBlankAsEmpty = _defaultCoercions.getAcceptBlankAsEmpty();
296	}
297	if (action == null) {
298	action = _defaultCoercions.findAction(CoercionInputShape.EmptyString);
299	}
300	
301	// First: if using blank as empty is no-go, return what caller specified
302	if (Boolean.FALSE.equals(acceptBlankAsEmpty)) {
303	return actionIfBlankNotAllowed;
304	}
305	// Otherwise, if action found, return that
306	if (action != null) {
307	return action;
308	}
309	
310	// 23-Sep-2021, tatu: [databind#3234] Should default to "allow" for Scalar types
311	//    for backwards compatibility
312	if (_isScalarType(targetType)) {
313	return CoercionAction.AsNull;
314	}
315	
316	// If not, one specific legacy setting to consider...
317	if (config.isEnabled(DeserializationFeature.ACCEPT_EMPTY_STRING_AS_NULL_OBJECT)) {
318	return CoercionAction.AsNull;
319	}
320	
321	// But finally consider ultimate default to be "false" and so:
322	return actionIfBlankNotAllowed;
323	}
324	
325	protected boolean _isScalarType(LogicalType targetType) {
326	return (targetType == LogicalType.Float)
