194	// Usually should just get string value:
195	// 04-Sep-2020, tatu: for 2.11.3 / 2.12.0, removed "FIELD_NAME" as allowed;
196	//   did not work and gave odd error message.
197	if (p.hasToken(JsonToken.VALUE_STRING)) {
