201	// But let's consider int acceptable as well (if within ordinal range)
202	if (p.hasToken(JsonToken.VALUE_NUMBER_INT)) {
203	// 26-Sep-2021, tatu: [databind#1850] Special case where we get "true" integer
204	//    enumeration and should avoid use of {@code Enum.index()}
