220	protected Object _fromString(JsonParser p, DeserializationContext ctxt,
221	String text)
222	throws IOException
223	{
224	CompactStringObjectMap lookup = ctxt.isEnabled(DeserializationFeature.READ_ENUMS_USING_TO_STRING)
225	? _getToStringLookup(ctxt) : _lookupByName;
226	Object result = lookup.find(text);
227	if (result == null) {
228	String trimmed = text.trim();
229	if ((trimmed == text) || (result = lookup.find(trimmed)) == null) {
230	return _deserializeAltString(p, ctxt, lookup, trimmed);
231	}
232	}
233	return result;
234	}
