287	private final Object _deserializeAltString(JsonParser p, DeserializationContext ctxt,
288	CompactStringObjectMap lookup, String nameOrig) throws IOException
289	{
290	String name = nameOrig.trim();
291	if (name.isEmpty()) { // empty or blank
292	// 07-Jun-2021, tatu: [databind#3171] Need to consider Default value first
293	//   (alas there's bit of duplication here)
294	if ((_enumDefaultValue != null)
295	&& ctxt.isEnabled(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_USING_DEFAULT_VALUE)) {
296	return _enumDefaultValue;
297	}
298	if (ctxt.isEnabled(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL)) {
299	return null;
300	}
301	
302	CoercionAction act;
303	if (nameOrig.isEmpty()) {
304	act = _findCoercionFromEmptyString(ctxt);
305	act = _checkCoercionFail(ctxt, act, handledType(), nameOrig,
306	"empty String (\"\")");
307	} else {
308	act = _findCoercionFromBlankString(ctxt);
309	act = _checkCoercionFail(ctxt, act, handledType(), nameOrig,
310	"blank String (all whitespace)");
311	}
312	switch (act) {
313	case AsEmpty:
314	case TryConvert:
315	return getEmptyValue(ctxt);
316	case AsNull:
317	default: // Fail already handled earlier
318	}
319	return null;
320	//            if (ctxt.isEnabled(DeserializationFeature.ACCEPT_EMPTY_STRING_AS_NULL_OBJECT)) {
321	} else {
322	// [databind#1313]: Case insensitive enum deserialization
323	if (Boolean.TRUE.equals(_caseInsensitive)) {
324	Object match = lookup.findCaseInsensitive(name);
325	if (match != null) {
326	return match;
327	}
328	} else if (!ctxt.isEnabled(DeserializationFeature.FAIL_ON_NUMBERS_FOR_ENUMS)
329	&& !_isFromIntValue) {
330	// [databind#149]: Allow use of 'String' indexes as well -- unless prohibited (as per above)
331	char c = name.charAt(0);
332	if (c >= '0' && c <= '9') {
333	try {
334	int index = Integer.parseInt(name);
335	if (!ctxt.isEnabled(MapperFeature.ALLOW_COERCION_OF_SCALARS)) {
336	return ctxt.handleWeirdStringValue(_enumClass(), name,
337	"value looks like quoted Enum index, but `MapperFeature.ALLOW_COERCION_OF_SCALARS` prevents use"
338	);
339	}
340	if (index >= 0 && index < _enumsByIndex.length) {
341	return _enumsByIndex[index];
342	}
343	} catch (NumberFormatException e) {
344	// fine, ignore, was not an integer
345	}
346	}
347	}
348	}
349	if ((_enumDefaultValue != null)
350	&& ctxt.isEnabled(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_USING_DEFAULT_VALUE)) {
351	return _enumDefaultValue;
352	}
353	if (ctxt.isEnabled(DeserializationFeature.READ_UNKNOWN_ENUM_VALUES_AS_NULL)) {
354	return null;
355	}
356	return ctxt.handleWeirdStringValue(_enumClass(), name,
357	"not one of the values accepted for Enum class: %s",  lookup.keys());
358	}
