62	}
63	
64	@JRubyMethod
65	public final IRubyObject write(final ThreadContext context, final IRubyObject event,
66	final IRubyObject reason) {
67	return doWrite(context, event, reason);
68	}
69	
70	@JRubyMethod
71	public final IRubyObject close(final ThreadContext context) {
72	return doClose(context);
73	}
