136	@JRubyClass(name = "PluginDeadLetterQueueWriter")
137	public static final class PluginDeadLetterQueueWriterExt
138	extends AbstractDeadLetterQueueWriterExt {
139	
140	private static final long serialVersionUID = 1L;
141	
142	private IRubyObject writerWrapper;
143	
144	private DeadLetterQueueWriter innerWriter;
145	
146	private IRubyObject pluginId;
147	
148	private IRubyObject pluginType;
149	
150	private String pluginIdString;
151	
152	private String pluginTypeString;
153	
154	public PluginDeadLetterQueueWriterExt(final Ruby runtime, final RubyClass metaClass) {
155	super(runtime, metaClass);
156	}
157	
158	@JRubyMethod
159	public AbstractDeadLetterQueueWriterExt.PluginDeadLetterQueueWriterExt initialize(
160	final ThreadContext context, final IRubyObject innerWriter, final IRubyObject pluginId,
161	final IRubyObject pluginType) {
162	writerWrapper = innerWriter;
163	if (writerWrapper.getJavaClass().equals(DeadLetterQueueWriter.class)) {
164	this.innerWriter = writerWrapper.toJava(
165	DeadLetterQueueWriter.class
166	);
167	}
168	this.pluginId = pluginId;
169	if (!pluginId.isNil()) {
170	pluginIdString = pluginId.asJavaString();
171	}
172	this.pluginType = pluginType;
173	if (!pluginType.isNil()) {
174	pluginTypeString = pluginType.asJavaString();
175	}
176	return this;
177	}
178	
179	@Override
180	protected IRubyObject getPluginId(final ThreadContext context) {
181	return pluginId;
182	}
183	
184	@Override
185	protected IRubyObject getPluginType(final ThreadContext context) {
186	return pluginType;
187	}
188	
189	@Override
190	protected IRubyObject getInnerWriter(final ThreadContext context) {
191	return writerWrapper;
192	}
193	
194	@Override
195	protected IRubyObject doWrite(final ThreadContext context, final IRubyObject event,
196	final IRubyObject reason) {
197	if (hasOpenWriter()) {
198	try {
199	innerWriter.writeEntry(
200	((JrubyEventExtLibrary.RubyEvent) event).getEvent(),
201	pluginIdString, pluginTypeString, reason.asJavaString()
202	);
203	} catch (final IOException ex) {
204	throw new IllegalStateException(ex);
205	}
206	}
207	return context.nil;
208	}
209	
210	@Override
211	protected IRubyObject doClose(final ThreadContext context) {
212	if (hasOpenWriter()) {
213	innerWriter.close();
214	}
215	return context.nil;
216	}
217	
218	@Override
219	protected RubyBoolean open(final ThreadContext context) {
220	return context.runtime.newBoolean(hasOpenWriter());
221	}
222	
223	private boolean hasOpenWriter() {
224	return innerWriter != null && innerWriter.isOpen();
225	}
226	}
227	}
