40	
41	import org.apache.logging.log4j.LogManager;
42	import org.apache.logging.log4j.Logger;
43	import org.logstash.common.io.DeadLetterQueueWriter;
44	import org.logstash.common.io.QueueStorageType;
45	
46	import java.io.IOException;
47	import java.nio.file.Paths;
48	import java.time.Duration;
49	import java.util.concurrent.ConcurrentHashMap;
50	
51	/**
52	* This class manages static collection of {@link DeadLetterQueueWriter} instances that
53	* can be created and retrieved by a specific String-valued key.
54	*/
55	public class DeadLetterQueueFactory {
56	
57	private static final Logger logger = LogManager.getLogger(DeadLetterQueueFactory.class);
58	private static final ConcurrentHashMap<String, DeadLetterQueueWriter> REGISTRY = new ConcurrentHashMap<>();
59	private static final long MAX_SEGMENT_SIZE_BYTES = 10 * 1024 * 1024;
60	
61	/**
62	* This class is only meant to be used statically, and therefore
63	* the constructor is private.
64	*/
65	private DeadLetterQueueFactory() {
66	}
67	
68	/**
69	* Retrieves an existing {@link DeadLetterQueueWriter} associated with the given id, or
70	* opens a new one to be returned. It is the retrievers responsibility to close these newly
71	* created writers.
72	*
73	* @param id The identifier context for this dlq manager
74	* @param dlqPath The path to use for the queue's backing data directory. contains sub-directories
75	*                for each id
76	* @param maxQueueSize Maximum size of the dead letter queue (in bytes). No entries will be written
77	*                     that would make the size of this dlq greater than this value
78	* @param flushInterval Maximum duration between flushes of dead letter queue files if no data is sent.
79	* @param storageType overwriting type in case of queue full: drop_older or drop_newer.
80	* @return The write manager for the specific id's dead-letter-queue context
81	*/
82	public static DeadLetterQueueWriter getWriter(String id, String dlqPath, long maxQueueSize, Duration flushInterval, QueueStorageType storageType) {
83	return REGISTRY.computeIfAbsent(id, key -> newWriter(key, dlqPath, maxQueueSize, flushInterval, storageType));
84	}
85	
86	public static DeadLetterQueueWriter release(String id) {
87	return REGISTRY.remove(id);
88	}
89	
90	private static DeadLetterQueueWriter newWriter(final String id, final String dlqPath, final long maxQueueSize,
91	final Duration flushInterval, final QueueStorageType storageType) {
92	try {
93	return new DeadLetterQueueWriter(Paths.get(dlqPath, id), MAX_SEGMENT_SIZE_BYTES, maxQueueSize, flushInterval, storageType);
94	} catch (IOException e) {
95	logger.error("unable to create dead letter queue writer", e);
96	}
97	return null;
98	}
99	}
