53	import java.util.concurrent.ScheduledExecutorService;
54	import java.util.concurrent.TimeUnit;
55	import java.util.concurrent.atomic.AtomicBoolean;
56	import java.util.concurrent.atomic.LongAdder;
57	import java.util.concurrent.locks.ReentrantLock;
58	import java.util.stream.Collectors;
59	import java.util.stream.Stream;
60	
61	import com.google.common.annotations.VisibleForTesting;
62	import org.apache.logging.log4j.LogManager;
63	import org.apache.logging.log4j.Logger;
64	import org.logstash.DLQEntry;
65	import org.logstash.Event;
66	import org.logstash.FieldReference;
67	import org.logstash.FileLockFactory;
68	import org.logstash.Timestamp;
69	
70	import static org.logstash.common.io.RecordIOWriter.RECORD_HEADER_SIZE;
71	import static org.logstash.common.io.RecordIOReader.SegmentStatus;
72	
73	public final class DeadLetterQueueWriter implements Closeable {
74	
75	@VisibleForTesting
76	static final String SEGMENT_FILE_PATTERN = "%d.log";
77	private static final Logger logger = LogManager.getLogger(DeadLetterQueueWriter.class);
78	private enum FinalizeWhen {ALWAYS, ONLY_IF_STALE};
79	private static final String TEMP_FILE_PATTERN = "%d.log.tmp";
80	private static final String LOCK_FILE = ".lock";
81	private final ReentrantLock lock = new ReentrantLock();
82	private static final FieldReference DEAD_LETTER_QUEUE_METADATA_KEY =
83	FieldReference.from(String.format("%s[dead_letter_queue]", Event.METADATA_BRACKETS));
84	private final long maxSegmentSize;
85	private final long maxQueueSize;
86	private final QueueStorageType storageType;
87	private LongAdder currentQueueSize;
88	private final Path queuePath;
89	private final FileLock fileLock;
90	private volatile RecordIOWriter currentWriter;
91	private int currentSegmentIndex;
92	private Timestamp lastEntryTimestamp;
93	private Duration flushInterval;
94	private Instant lastWrite;
95	private final AtomicBoolean open = new AtomicBoolean(true);
96	private ScheduledExecutorService flushScheduler;
97	
98	public DeadLetterQueueWriter(final Path queuePath, final long maxSegmentSize, final long maxQueueSize,
99	final Duration flushInterval) throws IOException {
100	this(queuePath, maxSegmentSize, maxQueueSize, flushInterval, QueueStorageType.DROP_NEWER);
101	}
102	
103	public DeadLetterQueueWriter(final Path queuePath, final long maxSegmentSize, final long maxQueueSize,
104	final Duration flushInterval, final QueueStorageType storageType) throws IOException {
105	this.fileLock = FileLockFactory.obtainLock(queuePath, LOCK_FILE);
106	this.queuePath = queuePath;
107	this.maxSegmentSize = maxSegmentSize;
108	this.maxQueueSize = maxQueueSize;
109	this.storageType = storageType;
110	this.flushInterval = flushInterval;
111	this.currentQueueSize = new LongAdder();
112	this.currentQueueSize.add(getStartupQueueSize());
113	
114	cleanupTempFiles();
115	currentSegmentIndex = getSegmentPaths(queuePath)
116	.map(s -> s.getFileName().toString().split("\\.")[0])
117	.mapToInt(Integer::parseInt)
118	.max().orElse(0);
119	nextWriter();
120	this.lastEntryTimestamp = Timestamp.now();
121	createFlushScheduler();
122	}
123	
124	public boolean isOpen() {
125	return open.get();
126	}
127	
128	public Path getPath(){
129	return queuePath;
130	}
131	
132	public long getCurrentQueueSize() {
133	return currentQueueSize.longValue();
134	}
135	
136	public String getStoragePolicy() {
137	return storageType.name().toLowerCase(Locale.ROOT);
138	}
139	
140	public void writeEntry(Event event, String pluginName, String pluginId, String reason) throws IOException {
141	writeEntry(new DLQEntry(event, pluginName, pluginId, reason));
142	}
143	
144	@Override
145	public void close() {
146	if (open.compareAndSet(true, false)) {
147	try {
148	finalizeSegment(FinalizeWhen.ALWAYS);
149	} catch (Exception e) {
150	logger.warn("Unable to close dlq writer, ignoring", e);
151	}
152	try {
153	releaseFileLock();
154	} catch (Exception e) {
155	logger.warn("Unable to release fileLock, ignoring", e);
156	}
157	
158	try {
159	flushScheduler.shutdown();
160	} catch (Exception e) {
161	logger.warn("Unable shutdown flush scheduler, ignoring", e);
162	}
163	}
164	}
165	
166	static Stream<Path> getSegmentPaths(Path path) throws IOException {
167	return listFiles(path, ".log");
168	}
169	
170	@VisibleForTesting
171	void writeEntry(DLQEntry entry) throws IOException {
172	lock.lock();
173	try {
174	Timestamp entryTimestamp = Timestamp.now();
175	if (entryTimestamp.compareTo(lastEntryTimestamp) < 0) {
176	entryTimestamp = lastEntryTimestamp;
177	}
178	innerWriteEntry(entry);
179	lastEntryTimestamp = entryTimestamp;
180	} finally {
181	lock.unlock();
182	}
183	}
184	
185	private void innerWriteEntry(DLQEntry entry) throws IOException {
186	Event event = entry.getEvent();
187	
188	if (alreadyProcessed(event)) {
189	logger.warn("Event previously submitted to dead letter queue. Skipping...");
190	return;
191	}
192	byte[] record = entry.serialize();
193	int eventPayloadSize = RECORD_HEADER_SIZE + record.length;
194	if (currentQueueSize.longValue() + eventPayloadSize > maxQueueSize) {
195	if (storageType == QueueStorageType.DROP_NEWER) {
196	logger.error("cannot write event to DLQ(path: " + this.queuePath + "): reached maxQueueSize of " + maxQueueSize);
197	return;
198	} else {
199	do {
200	dropTailSegment();
201	} while (currentQueueSize.longValue() + eventPayloadSize > maxQueueSize);
202	}
203	}
204	if (currentWriter.getPosition() + eventPayloadSize > maxSegmentSize) {
205	finalizeSegment(FinalizeWhen.ALWAYS);
206	}
207	currentQueueSize.add(currentWriter.writeEvent(record));
208	lastWrite = Instant.now();
209	}
210	
211	// package-private for testing
212	void dropTailSegment() throws IOException {
213	// remove oldest segment
214	final Optional<Path> oldestSegment = getSegmentPaths(queuePath)
215	.min(Comparator.comparingInt(DeadLetterQueueUtils::extractSegmentId));
216	if (!oldestSegment.isPresent()) {
217	throw new IllegalStateException("Listing of DLQ segments resulted in empty set during storage policy size(" + maxQueueSize + ") check");
218	}
219	final Path beheadedSegment = oldestSegment.get();
220	final long segmentSize = Files.size(beheadedSegment);
221	currentQueueSize.add(-segmentSize);
222	Files.delete(beheadedSegment);
223	logger.debug("Deleted exceeded retained size segment file {}", beheadedSegment);
224	}
225	
226	/**
227	* Method to determine whether the event has already been processed by the DLQ - currently this
228	* just checks the metadata to see if metadata has been added to the event that indicates that
229	* it has already gone through the DLQ.
230	* TODO: Add metadata around 'depth' to enable >1 iteration through the DLQ if required.
231	* @param event Logstash Event
232	* @return boolean indicating whether the event is eligible to be added to the DLQ
233	*/
234	private static boolean alreadyProcessed(final Event event) {
235	return event.includes(DEAD_LETTER_QUEUE_METADATA_KEY);
236	}
237	
238	private void flushCheck() {
239	try{
240	finalizeSegment(FinalizeWhen.ONLY_IF_STALE);
241	} catch (Exception e){
242	logger.warn("unable to finalize segment", e);
243	}
244	}
245	
246	/**
247	* Determines whether the current writer is stale. It is stale if writes have been performed, but the
248	* last time it was written is further in the past than the flush interval.
249	* @return
250	*/
251	private boolean isCurrentWriterStale(){
252	return currentWriter.isStale(flushInterval);
253	}
254	
255	private void finalizeSegment(final FinalizeWhen finalizeWhen) throws IOException {
256	lock.lock();
257	try {
258	if (!isCurrentWriterStale() && finalizeWhen == FinalizeWhen.ONLY_IF_STALE)
259	return;
260	
261	if (currentWriter != null && currentWriter.hasWritten()) {
262	currentWriter.close();
263	Files.move(queuePath.resolve(String.format(TEMP_FILE_PATTERN, currentSegmentIndex)),
264	queuePath.resolve(String.format(SEGMENT_FILE_PATTERN, currentSegmentIndex)),
265	StandardCopyOption.ATOMIC_MOVE);
266	if (isOpen()) {
267	nextWriter();
268	}
269	}
270	} finally {
271	lock.unlock();
272	}
273	}
274	
275	private void createFlushScheduler() {
276	flushScheduler = Executors.newScheduledThreadPool(1, r -> {
277	Thread t = new Thread(r);
278	//Allow this thread to die when the JVM dies
279	t.setDaemon(true);
280	//Set the name
281	t.setName("dlq-flush-check");
282	return t;
283	});
284	flushScheduler.scheduleAtFixedRate(this::flushCheck, 1L, 1L, TimeUnit.SECONDS);
285	}
286	
287	private long getStartupQueueSize() throws IOException {
288	return getSegmentPaths(queuePath)
289	.mapToLong((p) -> {
290	try {
291	return Files.size(p);
292	} catch (IOException e) {
293	throw new IllegalStateException(e);
294	}
295	} )
296	.sum();
297	}
298	
299	private void releaseFileLock() {
300	try {
301	FileLockFactory.releaseLock(fileLock);
302	} catch (IOException e) {
303	logger.debug("Unable to release fileLock", e);
304	}
305	try {
306	Files.deleteIfExists(queuePath.resolve(LOCK_FILE));
307	} catch (IOException e){
308	logger.debug("Unable to delete fileLock file", e);
309	}
310	}
311	
312	private void nextWriter() throws IOException {
313	currentWriter = new RecordIOWriter(queuePath.resolve(String.format(TEMP_FILE_PATTERN, ++currentSegmentIndex)));
314	currentQueueSize.increment();
315	}
316	
317	// Clean up existing temp files - files with an extension of .log.tmp. Either delete them if an existing
318	// segment file with the same base name exists, or rename the
319	// temp file to the segment file, which can happen when a process ends abnormally
320	private void cleanupTempFiles() throws IOException {
321	DeadLetterQueueWriter.listFiles(queuePath, ".log.tmp")
322	.forEach(this::cleanupTempFile);
323	}
324	
325	private static Stream<Path> listFiles(Path path, String suffix) throws IOException {
326	try(final Stream<Path> files = Files.list(path)) {
327	return files.filter(p -> p.toString().endsWith(suffix))
328	.collect(Collectors.toList()).stream();
329	}
330	}
331	
332	// check if there is a corresponding .log file - if yes delete the temp file, if no atomic move the
333	// temp file to be a new segment file..
334	private void cleanupTempFile(final Path tempFile) {
335	String segmentName = tempFile.getFileName().toString().split("\\.")[0];
336	Path segmentFile = queuePath.resolve(String.format("%s.log", segmentName));
337	try {
338	if (Files.exists(segmentFile)) {
339	Files.delete(tempFile);
340	}
341	else {
342	SegmentStatus segmentStatus = RecordIOReader.getSegmentStatus(tempFile);
343	switch (segmentStatus){
344	case VALID:
345	logger.debug("Moving temp file {} to segment file {}", tempFile, segmentFile);
346	Files.move(tempFile, segmentFile, StandardCopyOption.ATOMIC_MOVE);
347	break;
348	case EMPTY:
349	deleteTemporaryFile(tempFile, segmentName);
350	break;
351	case INVALID:
352	Path errorFile = queuePath.resolve(String.format("%s.err", segmentName));
353	logger.warn("Segment file {} is in an error state, saving as {}", segmentFile, errorFile);
354	Files.move(tempFile, errorFile, StandardCopyOption.ATOMIC_MOVE);
355	break;
356	default:
357	throw new IllegalStateException("Unexpected value: " + RecordIOReader.getSegmentStatus(tempFile));
358	}
359	}
360	} catch (IOException e){
361	throw new IllegalStateException("Unable to clean up temp file: " + tempFile, e);
362	}
363	}
364	
365	// Windows can leave files in a "Delete pending" state, where the file presents as existing to certain
366	// methods, and not to others, and actively prevents a new file being created with the same file name,
367	// throwing AccessDeniedException. This method moves the temporary file to a .del file before
368	// deletion, enabling a new temp file to be created in its place.
369	private void deleteTemporaryFile(Path tempFile, String segmentName) throws IOException {
370	Path deleteTarget;
371	if (isWindows()) {
372	Path deletedFile = queuePath.resolve(String.format("%s.del", segmentName));
373	logger.debug("Moving temp file {} to {}", tempFile, deletedFile);
374	deleteTarget = deletedFile;
375	Files.move(tempFile, deletedFile, StandardCopyOption.ATOMIC_MOVE);
376	} else {
377	deleteTarget = tempFile;
378	}
379	Files.delete(deleteTarget);
380	}
381	
382	private static boolean isWindows(){
383	return System.getProperty("os.name").startsWith("Windows");
384	}
385	}
