167	private static Object resolve(Object mock) {
168	if (mock instanceof Class<?>) { // static mocks are resolved by definition
169	return mock;
170	}
171	for (MockResolver mockResolver : Plugins.getMockResolvers()) {
172	mock = mockResolver.resolve(mock);
173	}
174	return mock;
175	}
