475	/** FIO_remove() :
476	 * @result : Unlink `fileName`, even if it's read-only */
477	static int FIO_remove(const char* path)
478	{
479	    if (!UTIL_isRegularFile(path)) {
480	        DISPLAYLEVEL(2, "zstd: Refusing to remove non-regular file %s \n", path);
481	        return 0;
482	    }
483	#if defined(_WIN32) || defined(WIN32)
484	    /* windows doesn't allow remove read-only files,
485	     * so try to make it writable first */
486	    chmod(path, _S_IWRITE);
487	#endif
488	    return remove(path);
489	}
