491	/** FIO_openSrcFile() :
492	 *  condition : `srcFileName` must be non-NULL.
493	 * @result : FILE* to `srcFileName`, or NULL if it fails */
494	static FILE* FIO_openSrcFile(const char* srcFileName)
495	{
496	    assert(srcFileName != NULL);
497	    if (!strcmp (srcFileName, stdinmark)) {
498	        DISPLAYLEVEL(4,"Using stdin for input \n");

982	FIO_compressZstdFrame(FIO_prefs_t* const prefs,
983	                      const cRess_t* ressPtr,
984	                      const char* srcFileName, U64 fileSize,
985	                      int compressionLevel, U64* readsize)
986	{
987	    cRess_t const ress = *ressPtr;
988	    FILE* const srcFile = ress.srcFile;
989	    FILE* const dstFile = ress.dstFile;
990	    U64 compressedfilesize = 0;
991	    ZSTD_EndDirective directive = ZSTD_e_continue;
992	
993	    /* stats */
994	    ZSTD_frameProgression previous_zfp_update = { 0, 0, 0, 0, 0, 0 };
995	    ZSTD_frameProgression previous_zfp_correction = { 0, 0, 0, 0, 0, 0 };
996	    typedef enum { noChange, slower, faster } speedChange_e;
997	    speedChange_e speedChange = noChange;
998	    unsigned flushWaiting = 0;
999	    unsigned inputPresented = 0;
1000	    unsigned inputBlocked = 0;
1001	    unsigned lastJobID = 0;
1002	
1003	    DISPLAYLEVEL(6, "compression using zstd format \n");
1004	
1005	    /* init */
1006	    if (fileSize != UTIL_FILESIZE_UNKNOWN) {
1007	        CHECK(ZSTD_CCtx_setPledgedSrcSize(ress.cctx, fileSize));
1008	    } else if (prefs->streamSrcSize > 0) {
1009	      /* unknown source size; use the declared stream size */
1010	      CHECK( ZSTD_CCtx_setPledgedSrcSize(ress.cctx, prefs->streamSrcSize) );
1011	    }
1012	    (void)srcFileName;
1013	
1014	    /* Main compression loop */
1015	    do {
1016	        size_t stillToFlush;
1017	        /* Fill input Buffer */
1018	        size_t const inSize = fread(ress.srcBuffer, (size_t)1, ress.srcBufferSize, srcFile);
1019	        ZSTD_inBuffer inBuff = { ress.srcBuffer, inSize, 0 };
1020	        DISPLAYLEVEL(6, "fread %u bytes from source \n", (unsigned)inSize);
1021	        *readsize += inSize;
1022	
1023	        if ((inSize == 0) || (*readsize == fileSize))
1024	            directive = ZSTD_e_end;
1025	
1026	        stillToFlush = 1;
1027	        while ((inBuff.pos != inBuff.size)   /* input buffer must be entirely ingested */
1028	            || (directive == ZSTD_e_end && stillToFlush != 0) ) {
1029	
1030	            size_t const oldIPos = inBuff.pos;
1031	            ZSTD_outBuffer outBuff = { ress.dstBuffer, ress.dstBufferSize, 0 };
1032	            size_t const toFlushNow = ZSTD_toFlushNow(ress.cctx);
1033	            CHECK_V(stillToFlush, ZSTD_compressStream2(ress.cctx, &outBuff, &inBuff, directive));
1034	
1035	            /* count stats */
1036	            inputPresented++;
1037	            if (oldIPos == inBuff.pos) inputBlocked++;  /* input buffer is full and can't take any more : input speed is faster than consumption rate */
1038	            if (!toFlushNow) flushWaiting = 1;
1039	
1040	            /* Write compressed stream */
1041	            DISPLAYLEVEL(6, "ZSTD_compress_generic(end:%u) => input pos(%u)<=(%u)size ; output generated %u bytes \n",
1042	                            (unsigned)directive, (unsigned)inBuff.pos, (unsigned)inBuff.size, (unsigned)outBuff.pos);
1043	            if (outBuff.pos) {
1044	                size_t const sizeCheck = fwrite(ress.dstBuffer, 1, outBuff.pos, dstFile);
1045	                if (sizeCheck != outBuff.pos)
1046	                    EXM_THROW(25, "Write error : %s (cannot write compressed block)",
1047	                                    strerror(errno));
1048	                compressedfilesize += outBuff.pos;
1049	            }
1050	
1051	            /* display notification; and adapt compression level */

1005	    /* init */
1006	    if (fileSize != UTIL_FILESIZE_UNKNOWN) {
1007	        CHECK(ZSTD_CCtx_setPledgedSrcSize(ress.cctx, fileSize));
1008	    } else if (prefs->streamSrcSize > 0) {
1009	      /* unknown source size; use the declared stream size */
1010	      CHECK( ZSTD_CCtx_setPledgedSrcSize(ress.cctx, prefs->streamSrcSize) );
1011	    }
1012	    (void)srcFileName;
1013

1050	
1051	            /* display notification; and adapt compression level */
1052	            if (READY_FOR_UPDATE()) {
1053	                ZSTD_frameProgression const zfp = ZSTD_getFrameProgression(ress.cctx);
1054	                double const cShare = (double)zfp.produced / (zfp.consumed + !zfp.consumed/*avoid div0*/) * 100;
1055	
1056	                /* display progress notifications */
1057	                if (g_display_prefs.displayLevel >= 3) {
1058	                    DISPLAYUPDATE(3, "\r(L%i) Buffered :%4u MB - Consumed :%4u MB - Compressed :%4u MB => %.2f%% ",
1059	                                compressionLevel,
1060	                                (unsigned)((zfp.ingested - zfp.consumed) >> 20),
1061	                                (unsigned)(zfp.consumed >> 20),
1062	                                (unsigned)(zfp.produced >> 20),
1063	                                cShare );
1064	                } else {   /* summarized notifications if == 2; */
1065	                    DISPLAYLEVEL(2, "\rRead : %u ", (unsigned)(zfp.consumed >> 20));
1066	                    if (fileSize != UTIL_FILESIZE_UNKNOWN)
1067	                        DISPLAYLEVEL(2, "/ %u ", (unsigned)(fileSize >> 20));
1068	                    DISPLAYLEVEL(2, "MB ==> %2.f%% ", cShare);
1069	                    DELAY_NEXT_UPDATE();
1070	                }
1071	
1072	                /* adaptive mode : statistics measurement and speed correction */
1073	                if (prefs->adaptiveMode) {
1074	
1075	                    /* check output speed */
1076	                    if (zfp.currentJobID > 1) {  /* only possible if nbWorkers >= 1 */
1077	
1078	                        unsigned long long newlyProduced = zfp.produced - previous_zfp_update.produced;
1079	                        unsigned long long newlyFlushed = zfp.flushed - previous_zfp_update.flushed;
1080	                        assert(zfp.produced >= previous_zfp_update.produced);
1081	                        assert(prefs->nbWorkers >= 1);
1082	
1083	                        /* test if compression is blocked
1084	                         * either because output is slow and all buffers are full
1085	                         * or because input is slow and no job can start while waiting for at least one buffer to be filled.
1086	                         * note : exclude starting part, since currentJobID > 1 */
1087	                        if ( (zfp.consumed == previous_zfp_update.consumed)   /* no data compressed : no data available, or no more buffer to compress to, OR compression is really slow (compression of a single block is slower than update rate)*/
1088	                          && (zfp.nbActiveWorkers == 0)                       /* confirmed : no compression ongoing */
1089	                          ) {
1090	                            DISPLAYLEVEL(6, "all buffers full : compression stopped => slow down \n")
1091	                            speedChange = slower;
1092	                        }
1093	
1094	                        previous_zfp_update = zfp;
1095	
1096	                        if ( (newlyProduced > (newlyFlushed * 9 / 8))   /* compression produces more data than output can flush (though production can be spiky, due to work unit : (N==4)*block sizes) */
1097	                          && (flushWaiting == 0)                        /* flush speed was never slowed by lack of production, so it's operating at max capacity */
1098	                          ) {
1099	                            DISPLAYLEVEL(6, "compression faster than flush (%llu > %llu), and flushed was never slowed down by lack of production => slow down \n", newlyProduced, newlyFlushed);
1100	                            speedChange = slower;
1101	                        }

1100	                            speedChange = slower;
1101	                        }
1102	                        flushWaiting = 0;
1103	                    }
1104	
1105	                    /* course correct only if there is at least one new job completed */
1106	                    if (zfp.currentJobID > lastJobID) {
1107	                        DISPLAYLEVEL(6, "compression level adaptation check \n")
1108	
1109	                        /* check input speed */
1110	                        if (zfp.currentJobID > (unsigned)(prefs->nbWorkers+1)) {   /* warm up period, to fill all workers */
1111	                            if (inputBlocked <= 0) {
1112	                                DISPLAYLEVEL(6, "input is never blocked => input is slower than ingestion \n");
1113	                                speedChange = slower;
1114	                            } else if (speedChange == noChange) {
1115	                                unsigned long long newlyIngested = zfp.ingested - previous_zfp_correction.ingested;
1116	                                unsigned long long newlyConsumed = zfp.consumed - previous_zfp_correction.consumed;
1117	                                unsigned long long newlyProduced = zfp.produced - previous_zfp_correction.produced;
1118	                                unsigned long long newlyFlushed  = zfp.flushed  - previous_zfp_correction.flushed;
1119	                                previous_zfp_correction = zfp;
1120	                                assert(inputPresented > 0);
1121	                                DISPLAYLEVEL(6, "input blocked %u/%u(%.2f) - ingested:%u vs %u:consumed - flushed:%u vs %u:produced \n",
1122	                                                inputBlocked, inputPresented, (double)inputBlocked/inputPresented*100,
1123	                                                (unsigned)newlyIngested, (unsigned)newlyConsumed,
1124	                                                (unsigned)newlyFlushed, (unsigned)newlyProduced);
1125	                                if ( (inputBlocked > inputPresented / 8)     /* input is waiting often, because input buffers is full : compression or output too slow */
1126	                                  && (newlyFlushed * 33 / 32 > newlyProduced)  /* flush everything that is produced */
1127	                                  && (newlyIngested * 33 / 32 > newlyConsumed) /* input speed as fast or faster than compression speed */
1128	                                ) {
1129	                                    DISPLAYLEVEL(6, "recommend faster as in(%llu) >= (%llu)comp(%llu) <= out(%llu) \n",
1130	                                                    newlyIngested, newlyConsumed, newlyProduced, newlyFlushed);
1131	                                    speedChange = faster;
1132	                                }
1133	                            }
1134	                            inputBlocked = 0;
1135	                            inputPresented = 0;
1136	                        }
1137	
1138	                        if (speedChange == slower) {
1139	                            DISPLAYLEVEL(6, "slower speed , higher compression \n")
1140	                            compressionLevel ++;
1141	                            if (compressionLevel > ZSTD_maxCLevel()) compressionLevel = ZSTD_maxCLevel();
1142	                            if (compressionLevel > prefs->maxAdaptLevel) compressionLevel = prefs->maxAdaptLevel;
1143	                            compressionLevel += (compressionLevel == 0);   /* skip 0 */
1144	                            ZSTD_CCtx_setParameter(ress.cctx, ZSTD_c_compressionLevel, compressionLevel);
1145	                        }
1146	                        if (speedChange == faster) {
1147	                            DISPLAYLEVEL(6, "faster speed , lighter compression \n")
1148	                            compressionLevel --;
1149	                            if (compressionLevel < prefs->minAdaptLevel) compressionLevel = prefs->minAdaptLevel;
1150	                            compressionLevel -= (compressionLevel == 0);   /* skip 0 */
1151	                            ZSTD_CCtx_setParameter(ress.cctx, ZSTD_c_compressionLevel, compressionLevel);
1152	                        }
1153	                        speedChange = noChange;
1154	
1155	                        lastJobID = zfp.currentJobID;
1156	                    }  /* if (zfp.currentJobID > lastJobID) */
1157	                }  /* if (g_adaptiveMode) */
1158	            }  /* if (READY_FOR_UPDATE()) */
1159	        }  /* while ((inBuff.pos != inBuff.size) */
1160	    } while (directive != ZSTD_e_end);
1161	
1162	    if (ferror(srcFile)) {
1163	        EXM_THROW(26, "Read error : I/O error");
1164	    }
1165	    if (fileSize != UTIL_FILESIZE_UNKNOWN && *readsize != fileSize) {
1166	        EXM_THROW(27, "Read error : Incomplete read : %llu / %llu B",
1167	                (unsigned long long)*readsize, (unsigned long long)fileSize);
1168	    }
1169	
1170	    return compressedfilesize;
1171	}

1179	FIO_compressFilename_internal(FIO_prefs_t* const prefs,
1180	                              cRess_t ress,
1181	                              const char* dstFileName, const char* srcFileName,
1182	                              int compressionLevel)
1183	{
