266	MEM_STATIC U32 ZSTD_LLcode(U32 litLength)
267	{
268	    static const BYTE LL_Code[64] = {  0,  1,  2,  3,  4,  5,  6,  7,
269	                                       8,  9, 10, 11, 12, 13, 14, 15,
270	                                      16, 16, 17, 17, 18, 18, 19, 19,
271	                                      20, 20, 20, 20, 21, 21, 21, 21,
272	                                      22, 22, 22, 22, 22, 22, 22, 22,
273	                                      23, 23, 23, 23, 23, 23, 23, 23,
274	                                      24, 24, 24, 24, 24, 24, 24, 24,
275	                                      24, 24, 24, 24, 24, 24, 24, 24 };
276	    static const U32 LL_deltaCode = 19;
277	    return (litLength > 63) ? ZSTD_highbit32(litLength) + LL_deltaCode : LL_Code[litLength];
278	}
