297	/*! ZSTD_storeSeq() :
298	 *  Store a sequence (literal length, literals, offset code and match length code) into seqStore_t.
299	 *  `offsetCode` : distance to match + 3 (values 1-3 are repCodes).
300	 *  `mlBase` : matchLength - MINMATCH
301	*/
302	MEM_STATIC void ZSTD_storeSeq(seqStore_t* seqStorePtr, size_t litLength, const void* literals, U32 offsetCode, size_t mlBase)
303	{
304	#if defined(DEBUGLEVEL) && (DEBUGLEVEL >= 6)
305	    static const BYTE* g_start = NULL;
306	    if (g_start==NULL) g_start = (const BYTE*)literals;  /* note : index only works for compression within a single segment */
307	    {   U32 const pos = (U32)((const BYTE*)literals - g_start);
308	        DEBUGLOG(6, "Cpos%7u :%3u literals, match%4u bytes at offCode%7u",
309	               pos, (U32)litLength, (U32)mlBase+MINMATCH, (U32)offsetCode);
310	    }
311	#endif
312	    assert((size_t)(seqStorePtr->sequences - seqStorePtr->sequencesStart) < seqStorePtr->maxNbSeq);
313	    /* copy Literals */
314	    assert(seqStorePtr->maxNbLit <= 128 KB);
315	    assert(seqStorePtr->lit + litLength <= seqStorePtr->litStart + seqStorePtr->maxNbLit);
316	    ZSTD_wildcopy(seqStorePtr->lit, literals, litLength);
317	    seqStorePtr->lit += litLength;
318	
319	    /* literal Length */
320	    if (litLength>0xFFFF) {
321	        assert(seqStorePtr->longLengthID == 0); /* there can only be a single long length */
322	        seqStorePtr->longLengthID = 1;
323	        seqStorePtr->longLengthPos = (U32)(seqStorePtr->sequences - seqStorePtr->sequencesStart);
324	    }
325	    seqStorePtr->sequences[0].litLength = (U16)litLength;
326	
327	    /* match offset */
328	    seqStorePtr->sequences[0].offset = offsetCode + 1;
329	
330	    /* match Length */
331	    if (mlBase>0xFFFF) {
332	        assert(seqStorePtr->longLengthID == 0); /* there can only be a single long length */
333	        seqStorePtr->longLengthID = 2;
334	        seqStorePtr->longLengthPos = (U32)(seqStorePtr->sequences - seqStorePtr->sequencesStart);
335	    }
336	    seqStorePtr->sequences[0].matchLength = (U16)mlBase;
337	
338	    seqStorePtr->sequences++;
339	}
