345	static unsigned ZSTD_NbCommonBytes (size_t val)
346	{
347	    if (MEM_isLittleEndian()) {
348	        if (MEM_64bits()) {
349	#       if defined(_MSC_VER) && defined(_WIN64)
350	            unsigned long r = 0;
351	            _BitScanForward64( &r, (U64)val );
352	            return (unsigned)(r>>3);
353	#       elif defined(__GNUC__) && (__GNUC__ >= 4)
354	            return (__builtin_ctzll((U64)val) >> 3);
355	#       else
356	            static const int DeBruijnBytePos[64] = { 0, 0, 0, 0, 0, 1, 1, 2,
357	                                                     0, 3, 1, 3, 1, 4, 2, 7,
358	                                                     0, 2, 3, 6, 1, 5, 3, 5,
359	                                                     1, 3, 4, 4, 2, 5, 6, 7,
360	                                                     7, 0, 1, 2, 3, 3, 4, 6,
361	                                                     2, 6, 5, 5, 3, 4, 5, 6,
362	                                                     7, 1, 2, 4, 6, 4, 4, 5,
363	                                                     7, 2, 6, 5, 7, 6, 7, 7 };
364	            return DeBruijnBytePos[((U64)((val & -(long long)val) * 0x0218A392CDABBD3FULL)) >> 58];
365	#       endif
366	        } else { /* 32 bits */
367	#       if defined(_MSC_VER)
368	            unsigned long r=0;
369	            _BitScanForward( &r, (U32)val );
370	            return (unsigned)(r>>3);
371	#       elif defined(__GNUC__) && (__GNUC__ >= 3)
372	            return (__builtin_ctz((U32)val) >> 3);
373	#       else
374	            static const int DeBruijnBytePos[32] = { 0, 0, 3, 0, 3, 1, 3, 0,
375	                                                     3, 2, 2, 1, 3, 2, 0, 1,
376	                                                     3, 3, 1, 2, 2, 2, 2, 0,
377	                                                     3, 1, 2, 0, 1, 0, 1, 1 };
378	            return DeBruijnBytePos[((U32)((val & -(S32)val) * 0x077CB531U)) >> 27];
379	#       endif
380	        }
381	    } else {  /* Big Endian CPU */
382	        if (MEM_64bits()) {
383	#       if defined(_MSC_VER) && defined(_WIN64)
384	            unsigned long r = 0;
385	            _BitScanReverse64( &r, val );
386	            return (unsigned)(r>>3);
387	#       elif defined(__GNUC__) && (__GNUC__ >= 4)
388	            return (__builtin_clzll(val) >> 3);
389	#       else
390	            unsigned r;
391	            const unsigned n32 = sizeof(size_t)*4;   /* calculate this way due to compiler complaining in 32-bits mode */
392	            if (!(val>>n32)) { r=4; } else { r=0; val>>=n32; }
393	            if (!(val>>16)) { r+=2; val>>=8; } else { val>>=24; }
394	            r += (!val);
395	            return r;
396	#       endif
397	        } else { /* 32 bits */
398	#       if defined(_MSC_VER)
399	            unsigned long r = 0;
400	            _BitScanReverse( &r, (unsigned long)val );
401	            return (unsigned)(r>>3);

