299	jv binop_minus(jv a, jv b) {
300	if (jv_get_kind(a) == JV_KIND_NUMBER && jv_get_kind(b) == JV_KIND_NUMBER) {
301	jv r = jv_number(jv_number_value(a) - jv_number_value(b));
302	jv_free(a);
303	jv_free(b);
304	return r;
305	} else if (jv_get_kind(a) == JV_KIND_ARRAY && jv_get_kind(b) == JV_KIND_ARRAY) {
306	jv out = jv_array();
307	jv_array_foreach(a, i, x) {
308	int include = 1;
309	jv_array_foreach(b, j, y) {
310	if (jv_equal(jv_copy(x), y)) {
311	include = 0;
312	break;
313	}
314	}
315	if (include)
316	out = jv_array_append(out, jv_copy(x));
317	jv_free(x);
318	}
319	jv_free(a);
320	jv_free(b);
321	return out;
322	} else {
323	return type_error2(a, b, "cannot be subtracted");
324	}
