+    fprintf(stderr, "jq: dry run: %s (set JQ_ENABLE_SNAPSHOT=1)\n", name_str);
+  } else {
+    FILE *fp = fopen(name_str, "wb");
+    if (!fp) {
+      //perror("fopen");
+      fprintf(stderr, "jq: error: could not open %s for writing\n", name_str);
+    } else {
+      if (jv_get_kind(data) == JV_KIND_STRING)
