207	inline auto clz(uint32_t x) -> int {
208	  unsigned long r = 0;
209	  _BitScanReverse(&r, x);
210	  FMT_ASSERT(x != 0, "");
211	  // Static analysis complains about using uninitialized data
212	  // "r", but the only way that can happen is if "x" is 0,
213	  // which the callers guarantee to not happen.
214	  FMT_MSC_WARNING(suppress : 6102)
215	  return 31 ^ static_cast<int>(r);
216	}
