26	
27	/*!
28	@brief abstract input adapter interface
29	
30	Produces a stream of std::char_traits<char>::int_type characters from a
31	std::istream, a buffer, or some other input type.  Accepts the return of exactly
32	one non-EOF character for future input.  The int_type characters returned
33	consist of all valid char values as positive values (typically unsigned char),
34	plus an EOF value outside that range, specified by the value of the function
35	std::char_traits<char>::eof().  This value is typically -1, but could be any
36	arbitrary value which is not a valid char value.
37	*/
38	struct input_adapter_protocol
39	{
40	/// get a character [0,255] or std::char_traits<char>::eof().
41	virtual std::char_traits<char>::int_type get_character() = 0;
42	/// restore the last non-eof() character to input
43	virtual void unget_character() = 0;
44	virtual ~input_adapter_protocol() = default;
45	};
46	
47	/// a type to simplify interfaces
48	using input_adapter_t = std::shared_ptr<input_adapter_protocol>;
49	
50	/*!
51	Input adapter for a (caching) istream. Ignores a UFT Byte Order Mark at
52	beginning of input. Does not support changing the underlying std::streambuf
53	in mid-input. Maintains underlying std::istream and std::streambuf to support
54	subsequent use of standard std::istream operations to process any input
55	characters following those used in parsing the JSON input.  Clears the
56	std::istream flags; any input errors (e.g., EOF) will be detected by the first
57	subsequent call for input from the std::istream.
58	*/
59	class input_stream_adapter : public input_adapter_protocol
60	{
61	public:
62	~input_stream_adapter() override
63	{
64	// clear stream flags; we use underlying streambuf I/O, do not
65	// maintain ifstream flags
66	is.clear();
67	}
68	
69	explicit input_stream_adapter(std::istream& i)
70	: is(i), sb(*i.rdbuf())
71	{
72	// skip byte order mark
73	std::char_traits<char>::int_type c;
74	if ((c = get_character()) == 0xEF)
75	{
76	if ((c = get_character()) == 0xBB)
77	{
78	if ((c = get_character()) == 0xBF)
79	{
80	return; // Ignore BOM
81	}
82	else if (c != std::char_traits<char>::eof())
83	{
84	is.unget();
85	}
86	is.putback('\xBB');
87	}
88	else if (c != std::char_traits<char>::eof())
89	{
90	is.unget();
91	}
92	is.putback('\xEF');
93	}
94	else if (c != std::char_traits<char>::eof())
95	{
96	is.unget(); // no byte order mark; process as usual
97	}
98	}
99	
100	// delete because of pointer members
101	input_stream_adapter(const input_stream_adapter&) = delete;
102	input_stream_adapter& operator=(input_stream_adapter&) = delete;
103	
104	// std::istream/std::streambuf use std::char_traits<char>::to_int_type, to
105	// ensure that std::char_traits<char>::eof() and the character 0xFF do not
106	// end up as the same value, eg. 0xFFFFFFFF.
107	std::char_traits<char>::int_type get_character() override
108	{
109	return sb.sbumpc();
110	}
111	
112	void unget_character() override
113	{
114	sb.sungetc();  // is.unget() avoided for performance
115	}
116	
117	private:
118	/// the associated input stream
119	std::istream& is;
120	std::streambuf& sb;
121	};
122	
123	/// input adapter for buffer input
124	class input_buffer_adapter : public input_adapter_protocol
125	{
126	public:
127	input_buffer_adapter(const char* b, const std::size_t l)
128	: cursor(b), limit(b + l), start(b)
129	{
130	// skip byte order mark
131	if (l >= 3 and b[0] == '\xEF' and b[1] == '\xBB' and b[2] == '\xBF')
132	{
133	cursor += 3;
134	}
135	}
136	
137	// delete because of pointer members
138	input_buffer_adapter(const input_buffer_adapter&) = delete;
139	input_buffer_adapter& operator=(input_buffer_adapter&) = delete;
140	
141	std::char_traits<char>::int_type get_character() noexcept override
142	{
143	if (JSON_LIKELY(cursor < limit))
144	{
145	return std::char_traits<char>::to_int_type(*(cursor++));
146	}
147	
148	return std::char_traits<char>::eof();
149	}
150	
151	void unget_character() noexcept override
152	{
153	if (JSON_LIKELY(cursor > start))
154	{
155	--cursor;
156	}
157	}
158	
159	private:
160	/// pointer to the current character
161	const char* cursor;
162	/// pointer past the last character
163	const char* limit;
164	/// pointer to the first character
165	const char* start;
166	};
